pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // However, we reward post_residuals that perfectly match or nearly match the next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 2. Fragment Avoidance: Penalize residuals that are too small to fit any likely future item 
    // (items < 20 are rare, so avoid leaving 1-19 gaps).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0;
    }

    // 3. New Bin Thresholding: If this is an empty bin, only pick it if we are desperate.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have very few options or the current mean residual is very high.
        if fitting_bins_count > 0 {
            score += 150.0 - (mean_residual * 1.5);
        } else {
            score -= 10.0;
        }
    }

    // 4. Tightness bias: If fitting_bins_count is 1, we are forced to use this bin. 
    // We lower the score to ensure we don't accidentally open a new bin instead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative with residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit typical items
    // If post_residual is small but > 0, it's often wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // Reward bins that leave exactly enough room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward bins that accommodate the next item comfortably
            score -= 20.0;
        } else {
            // Penalize bins that cannot fit the next item if they are the only option
            score += 15.0;
        }
    }

    // 3. Balance against global state:
    // If we have many open bins, prioritize tighter packing (lower residuals).
    // If we have few open bins, prioritize creating space for future items.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += (open_bins_count as f64) * fill_ratio * 5.0;

    // 4. Heuristic for New Bin (bin_residual == bin_capacity)
    // Only open a new bin if the current mean_residual is very low (we are packing tightly)
    // or if the current item is very large and doesn't fit well anywhere else.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // Must open
        } else {
            // Penalize opening a new bin if other options exist, unless it's a perfect fit
            score += 50.0 + (mean_residual * 0.5);
        }
    }

    // 5. Prefer bins that keep the mean residual balanced
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger residuals (Best-Fit principle)
    // We use a quadratic penalty to discourage leaving large gaps.
    let mut score = post * post * 0.01;

    // Lookahead logic: if next_item_size fits in the current post_residual, 
    // heavily reward this bin to keep the packing tight.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 5.0;
    }

    // Dynamic threshold: As the stream progresses, become more conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating a "New Bin" option.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we approach the end of the stream
        // to avoid stranding items in new bins.
        score += 25.0 + (progress * 50.0);

        // If there are existing bins that can fit the item, penalize the new bin heavily.
        if fitting_bins_count > 0 {
            score += 100.0 / (fitting_bins_count as f64 + 1.0);
        }
    } else {
        // For existing bins, reward bins that align with the global mean residual
        // to keep the distribution of remaining space uniform (balancing heuristic).
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Non-linear coupling: penalize small residual "slivers" that are too small to be useful
    // (e.g., residual < 10) unless they are exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating "slivers" (unusable space < 10): 
    // If the residual is small but not zero, it's often a dead-end.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if the next item is large, penalize small residuals 
    // that won't accommodate it, especially as the stream progresses.
    if next_item_size > 0 {
        let lookahead_penalty = if post_residual < next_item_size {
            20.0 * (1.0 + progress)
        } else {
            -5.0 * (1.0 - progress)
        };
        score += lookahead_penalty;
    }

    // New bin logic: discourage opening a new bin unless the remaining capacity 
    // in existing bins is highly fragmented.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or 
        // if fitting_bins_count is low, suggesting poor existing options.
        let fragmentation_pressure = (open_bins_count as f64) * (1.0 - (mean_residual / bin_capacity as f64));
        score += 30.0 - (fragmentation_pressure * 2.0);
    }

    // Global efficiency: favor bins that keep the overall mean_residual balanced.
    // This prevents one bin from becoming too "empty" compared to others.
    let residual_deviation = (post_res - mean_residual).abs();
    score += 0.5 * residual_deviation;

    score
