    // We want post_residual to be as small as possible (close to 0).
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward placements that leave "round" residuals
    // Penalize residuals that are not multiples of common item sizes or bin fractions
    if post_residual > 0 {
        score += (post_residual % 10) as f64 * 2.5;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, 
