        // Reward tighter packing if next item fits perfectly
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 4. Scarcity/Efficiency: Penalize opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity), add a high cost.
