    if progress > 0.8 && post_residual < 10 {
        score -= 10.0;
    }

    // 6. Mean Residual Balancing: Avoid creating outliers
    // Penalize if this bin's post_residual is significantly lower than the mean
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 5.0;
    }

    score
