pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best-Fit (smaller post_residual is better)
    let mut score = post;

    // Penalty for creating a "small gap" that is unlikely to be filled later
    // (Thresholding around 10-20, as items are >= 10)
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if next item is large, avoid leaving a small residual
    if next_item_size > 0 {
        if post < (next_item_size as f64) && post > 0.0 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic thresholding: Near the end of the stream, prioritize bin consolidation
    // more aggressively to minimize total open bins.
    let consolidation_pressure = progress * 20.0;
    score += (open_bins_count as f64) * consolidation_pressure;

    // Favor filling bins that are already closer to the mean_residual
    // This helps keep bins balanced and reduces fragmentation.
    let imbalance = (post_residual as f64 - mean_residual).abs();
    score += imbalance * 0.5;

    // New Bin Logic: Only open a new bin if the fit is extremely poor
    // (High post_residual is good for Best-Fit, but we want to avoid fragmentation)
    if bin_residual == bin_capacity {
        // High penalty to open new bin unless necessary
        score = 60.0 + (progress * 40.0);

        // If no bins can fit the item, reduce the penalty significantly
        if fitting_bins_count == 0 {
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score: prioritize smaller post_residual (Best Fit principle)
    // We penalize larger post_residuals quadratically to avoid fragmentation
    let mut score = post * post / capacity;

    // Penalty for creating "dead space" that cannot fit typical items
    // If the post_residual is small but large enough to be unusable (e.g., < 10), it's worse
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Dynamic Lookahead Coupling:
    // If next_item_size exists, favor bins that can accommodate it.
    // If the current post_residual is too small for the next item, penalize it.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post < next_item {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Global Bin Management:
    // As the stream progresses, prioritize closing bins (lower open_bins_count)
    // to keep the bin count low, but don't force it too early.
    score += (open_bins_count as f64) * progress * 2.0;

    // Handling the New Bin Candidate:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // We only open a new bin if the score of current bins is sufficiently high.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have very few bins open or the current fits are terrible
        // We set the baseline cost of a new bin high, scaling with progress.
        score = 45.0 + (progress * 15.0);

        // If there are bins that can fit the item, penalize opening a new one
        if fitting_bins_count > 0 {
            score += 40.0 / (fitting_bins_count as f64 + 1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: The post_residual (Best Fit principle).
    // We want to minimize post_residual to pack bins tightly.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open if the current fit is extremely inefficient (e.g., leaving a large gap)
    // or if the stream is nearing the end and we want to consolidate.
    if is_new_bin {
        // High base cost for opening a new bin, weighted by the number of bins already open.
        score = 45.0 + (open_bins_count as f64 * 2.5);

        // Dynamically reduce the cost of opening new bins as we approach the end of the stream
        // to encourage finishing items into new bins rather than forcing bad fits.
        score -= (progress * 20.0);
    } else {
        // For existing bins, apply a non-linear penalty for creating "fragmented" space.
        // We penalize post_residuals that are small but not zero (the "dead space" trap).
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // Lookahead heuristic: If the next item is large, avoid bins that will leave 
        // a small, unusable residual after the current item.
        if next_item_size > 0 {
            let next_post = post_residual as i32 - next_item_size as i32;
            if next_post < 0 && post_residual < 20 {
                score += 25.0; // Penalty for stranding an item that won't fit next
            }
        }
    }

    // Adjust score based on the mean residual of current bins to favor balancing
    // the load across available bins (prevents one bin from becoming too empty).
    if !is_new_bin {
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
