    }

    // 3. Dynamic exploration: As the stream progresses, become more conservative
    // about opening new bins. If it's a new bin (bin_residual == bin_capacity),
    // penalize based on how many fitting bins are available.
    if bin_residual == bin_capacity {
        // If we have other options, make opening a new bin expensive early on, 
        // but cheaper towards the end if we are running out of space.
        score += (fitting_bins_count as f64 * 15.0) * (1.0 - progress);
    } else {
        // 4. Global state coupling: If this bin's residual is significantly below
        // the mean, it is a "tight" bin. Favor filling it to consolidate fragmentation.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0 * (1.0 - (bin_residual as f64 / mean_residual));
        }
    }

    // 5. Hard constraint: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

