    if is_new_bin {
        // As the stream progresses, the penalty for opening a new bin decreases.
        // Penalty is scaled by the number of bins already open to discourage fragmentation.
        score += (1.0 - progress).powf(2.0) * 100.0 + (open_bins_count as f64 * 5.0);
    } else {
