    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    let mut score = post_res;

    // Penalty for creating "dead space": 
    // If post_residual is small but > 0, it is often a "bad" fit (fragmentation).
    // We penalize values in the [1, 15] range quadratically to favor tight fills or larger gaps.
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_res).powf(2.0) * 0.5;
    }

    // Lookahead logic:
    // If the next item exists, penalize bins that cannot fit the next item after this one.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding:
    // As the stream progresses, become more aggressive in packing to prevent opening new bins.
    // We penalize opening a new bin (where bin_residual == bin_capacity) increasingly as progress grows.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress.powf(2.0));
    }

    // Pressure relief:
    // If there are many open bins, penalize the creation of a new bin even further.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // Fitting efficiency:
    // If this is the only bin that can fit the item, give it a significant priority boost.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Global balance:
    // Favor bins that stay close to the mean residual to maintain uniform bin states.
    score += (post_res - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (residual too small to fit common items)
    // We heavily penalize residuals that are non-zero but smaller than 10 (the minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic packing: favor residuals that are multiples of 25 (e.g., 0, 25, 50, 75)
    // as they leave room for common item sizes like 25, 50, etc.
    let remainder = post_residual % 25;
    score += (remainder as f64) * 0.4;

    // If this bin is the only one that can fit the item, we are forced to use it.
    // We lower the score to ensure it is selected over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // If considering a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very small
        // or if we have very few bins open compared to the progress of the stream.
        let progress = step_index as f64 / total_items as f64;
        if mean_residual > 20.0 && open_bins_count > 2 {
            score += 40.0; // Discourage opening new bins early
        } else {
            score += 10.0; // Neutral baseline for new bin creation
        }
    }

    // Penalize large residuals that don't accommodate the next item well
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    score
}

