        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have many bins already open.
    // We only apply this to the "new bin" candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If we have other bins that could fit this item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Tightness bias: Favor bins where the residual stays close to the global mean, 
    // discouraging fragmentation across multiple bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins 
    // (tightening residual) over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
