    // Penalty for creating "dead space" that is too small for the next item
    // If the next item is larger than the post_residual, we create a bottleneck.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Dynamic pressure: As the stream nears the end, penalize opening new bins 
    // more aggressively to force consolidation.
    if bin_residual == bin_capacity {
        // This is the cost to open a new bin. 
        // We scale this by progress: opening a new bin is cheap early on, 
        // but very expensive (high score) near the end of the stream.
        score += 25.0 + (progress * 50.0);
    } else {
        // For existing bins, reward configurations that bring the bin residual 
        // closer to the global mean residual to maintain uniform bin utilization.
        let deviation = (post as f64 - mean_residual).abs();
        score -= deviation * 0.2;

        // If this is the only fitting bin, prioritize it to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Non-linear coupling: penalize small, inefficient residuals that are 
    // likely to remain empty (the "fragmentation" penalty).
    if post_residual > 0 && post_residual < 15 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tight (standard Best-Fit logic)
    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can accommodate it.
    //    If post_residual is smaller than next_item_size, we penalize the bin because it 
    //    creates "dead space" that cannot be filled by the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            // Reward bins that leave exactly enough space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.1;
        }
    }

    // 3. Harmonic Class Logic: Prefer filling bins to specific thresholds (e.g., 1/2, 1/3, 1/4 of capacity)
    //    We reward post_residuals that reach these "harmonic" remaining states.
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 4. New Bin Threshold: Discourage opening a new bin unless the current fit is catastrophic.
    //    If this is a new bin (bin_residual == bin_capacity), add a high penalty unless 
    //    fitting_bins_count is low (meaning we have no good choices).
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // 5. Mean Residual Balancing: If the current bin is significantly emptier than the average,
    //    penalize placing items here to force convergence toward the mean.
    if (bin_residual as f64) > mean_residual + 10.0 {
        score += 5.0;
    }

    // 6. Final progression weight: As we approach the end of the stream, be more aggressive
    //    with packing (reduce the penalty for tight fits).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If post_residual is in the range [1, 9], it is high-risk for stranded space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
