    // This creates a "Best-Fit" bias.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // 3. Open Bin Pressure: Penalize opening new bins when current ones have space.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Only prioritize this if we have very few bins open or if the item is large.
        score += 25.0 + (open_bins_count as f64 * 2.0);

