    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit typical future items (e.g., < 20).
    // The range 1..20 is highly problematic as it creates "orphaned" space.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Open Bin Pressure: Penalize opening a new bin if other bins are available.
    // Discourage new bin if fitting_bins_count > 0.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 80.0 + (open_bins_count as f64 * 5.0);
    }

    // 4. Mean Residual Balancing: If this bin's residual is significantly below the current mean, 
    // it is a "tight" bin. We prioritize keeping tight bins tight.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more aggressive 
    // about filling existing bins to prevent leftover bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 10 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on the current mean_residual to prevent 
    // fragmenting space when existing bins are already underutilized.
    if bin_residual == bin_capacity {
        score += mean_residual * 1.5;
        // If there are bins that could fit this item, make opening a new bin expensive.
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    } else {
        // 2. Best-Fit logic: prioritize bins where post_residual is minimized.
        // 3. Lookahead: reward bins where the post_residual is close to the next_item_size
        // to facilitate tight packing in the next step.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.4;
        }

        // 4. Penalty for "dead zones": if post_residual is small but not zero,
        // it often becomes unusable (e.g., < 10). Penalize these "sliver" residuals.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // 5. If this is the last chance for this bin (fitting_bins_count == 1), 
        // we are slightly more tolerant of the post_residual to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // 6. Normalize against progression: as the stream nears the end, 
    // prioritize closing off existing bins to avoid leftover capacity.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is almost full but leaves a small, useless gap (the "sliver" problem).
    // Specifically, gaps between 1 and 9 are often hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If we have a next item, try to ensure the post_residual can accommodate it.
    // If the next item cannot fit, we penalize the bin proportionally to the wasted potential.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        } else {
            // Reward bins that are "perfect matches" for the lookahead item.
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Dynamic constraint: If this is the only bin that can fit the item, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Global state awareness: If we have many open bins, penalize opening a new one.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) + (progress * 20.0);
    }

    // Balance against the mean residual: Prefer bins that stay close to the average utilization
    // to maintain a uniform distribution of empty space.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
