    if bin_residual == bin_capacity {
        // The cost of a new bin increases as we approach the end of the stream
        // to encourage filling existing capacity.
        score += (100.0 - mean_residual) * (1.0 + progress * 2.0);
    } else {
        // If the bin is already open, provide a slight incentive to use it
        // proportional to how much it helps reduce the global mean residual.
        score -= (bin_capacity as f64 - mean_residual) * 0.5;
    }

    // If this is the last chance to fit the item in existing bins, significantly lower the score
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
