pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Aggressive 2-step lookahead matching.
    // The goal is to minimize waste while ensuring the remaining space in a bin 
    // can accommodate the next item in the sequence.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalize opening a new bin heavily unless the current open bins are 
        // extremely inefficient (i.e., post_residual would be very small in existing bins).
        score = 85.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Reward placements that leave a residual space close to the next_item_size.
        // This is a "Best-Fit-Lookahead" approach.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
