pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that cannot fit common small items (e.g., < 20)
    // We prioritize bins where the post_residual is either 0 or large enough for future items.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // Reward: If this bin fits the next item perfectly (or close to it), prioritize it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = (post_residual - next_item_size) as f64;
        score -= (30.0 / (fit_margin + 1.0));
    }

    // Heuristic: If we are near the end of the stream, prioritize filling existing bins aggressively
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (100.0 - post_residual as f64) * 0.5;
    }

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // Only open if current bins are very full (mean_residual low)
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 150.0;
        } else {
            score += 60.0;
        }
    }

    // Harmonic class logic: Favor bins that leave a residual that is a multiple of 20
    // to keep bins aligned for potential future items of standard sizes.
    let remainder = post_residual % 20;
    if remainder == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // If this is the only fitting bin, heavily reward it to avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tighter packing (lower post_residual)
    let mut score = post_residual as f64;

    // Penalty for creating "unusable" small gaps (dead space < 10)
    // Small gaps are highly likely to be wasted given the item size range (10-100)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Penalty for opening a new bin if we have existing capacity
    // Scale this penalty by the current progress to be more conservative late-game
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 + progress);

        // If we have many open bins, penalize opening another one heavily
        score += (open_bins_count as f64) * 2.0;
    }

    // Lookahead logic: if next_item_size is large, favor larger post_residuals 
    // to keep the bin useful for the upcoming item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin will be useless for the next item, apply penalty
            score += 15.0;
        } else {
            // This bin is a good candidate for the next item, reward it
            score -= 10.0;
        }
    }

    // Pressure factor: if this is the only bin that fits, we are forced to use it.
    // Lower the score to ensure we don't prefer opening a new bin over this forced choice.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Balance against the mean residual to prevent fragmentation
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Aggressive 2-step lookahead matching.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalize opening new bins unless we are forced to or the current state is highly fragmented.
        // We favor opening a new bin if the mean residual of existing bins is already very low (high fragmentation).
        score += 85.0 - (mean_residual * 0.5);
    } else {
        // Reward placements that result in a post_residual that perfectly matches the next item.
        // This is the "Best Fit" refinement.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score -= 40.0 / (1.0 + diff);
