        // If this is the only bin that can fit the item, prioritize it to prevent unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Encourage keeping the mean residual balanced.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Progression scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

