        score += (open_bins_count as f64) * 2.0;
    } else {
        // If we are placing in an existing bin, favor bins that are closer to the mean_residual
        // to keep the "fill level" balanced across the bin set.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // If this is the only bin that can fit the item, heavily reward it to avoid 
