pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-Residual Minimization (HRM)
    // Minimizes post_residual while penalizing fragmentations that block future lookahead

    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: If we have multiple options, prioritize tighter fits.
    // The base score (post_residual) already incentivizes Best-Fit.

    // 2. Harmonic Class Penalty: 
    // If the post_residual is small (e.g., < 10), it is often "dead space" that cannot fit any item.
    // We penalize these "slivers" to force them into larger remaining spaces.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Synergy: 
    // If the next item can fit in the current post_residual, we reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Thresholding:
    // If this is the last chance for the current item (fitting_bins_count == 1), 
    // we should prioritize taking this bin unless it is an exceptionally poor fit.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // 5. New Bin Regulation:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the mean_residual of existing bins is already very low (highly fragmented).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // New bin is better than using a highly fragmented existing bin
            score += 5.0;
        } else {
            // Otherwise, strongly discourage opening a new bin
            score += 40.0;
        }
    }

    // 6. Progressive tightening:
    // As the stream nears completion, become more aggressive at filling remaining space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps that cannot fit common item sizes.
    // We prioritize bins that leave the bin nearly full (post_residual -> 0) or leave enough space for the next item.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
