            score -= 10.0;
        }
    }

    // 4. Tight Fit Reward: If the current item fills the bin perfectly, prioritize it.
    if post_residual == 0 {
        score -= 15.0;
    }

    // 5. Global Efficiency: If many bins are open, push towards packing existing bins tighter.
    if open_bins_count > 5 {
