}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), but we apply 
    // a non-linear penalty to avoid creating "orphaned" residuals that are 
    // too small to fit typical future items.

    // Base score: punish larger post_residuals
    let mut score = post * 1.5;

    // Non-linear coupling: As the stream progresses, favor tighter packing 
    // to avoid leaving fragmented space near the end.
    score += (post * post / bin_capacity as f64) * (1.0 + progress);

    // Lookahead logic: if next_item_size fits in the current post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
