    // Penalty for opening new bins: Only open a new bin if the current 
    // fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // If we are early in the stream, opening a new bin is cheap. 
        // If we are late, opening a new bin is expensive.
        score += 25.0 + (progress * 50.0);

        // If there are other bins that could fit the item, strongly discourage 
        // opening a new one unless the mean residual is already very high.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64 * 10.0) + (mean_residual * 0.5);
        }
    } else {
        // Encourage using existing bins that have residuals close to the mean,
        // reducing variance in bin fullness.
        let dev = (post - mean_residual).abs();
        score += dev * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // The objective is to minimize post_residual while avoiding "dead zones" 
    // that cannot accommodate the next_item_size or future small items.

    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (1..10) which is hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
