    // 2. Lookahead logic: If the next item can fit in the current post_residual,
    // reward this bin heavily to keep the item flow packed.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic balance: Penalize bins that deviate significantly from the mean_residual.
    // This promotes uniform filling across bins (Best-Fit principle).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Thresholding: If this is the last chance for the current item, 
    // force-reduce score to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
