}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space": 
    // If post_residual is too small to fit any likely future item (e.g., < 10), it is often better to 
    // keep a larger residual if possible.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead synergy:
    // If the post_residual can perfectly accommodate the next item, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (50.0 - diff).max(0.0);
    }

    // 4. Mean residual balancing:
    // Avoid creating bins that are significantly tighter than the average, which risks stranding 
    // larger items later.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 15.0;
    }

    // 5. New Bin logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if we are forced to (fitting_bins_count == 0) or if the current
    // fitting options are extremely poor (e.g., all result in tiny, unusable residuals).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if existing bins can take the item
            score += 60.0;
        } else {
            // Must open a new bin
            score = 0.0;
        }
    }

    // 6. Progressive tightening:
    // As we approach the end of the stream, prioritize packing density over flexibility.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
