    }

    // Encourage density: penalize opening a new bin (bin_residual == bin_capacity)
    // as the stream progresses to consolidate items.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // Global load balancing: penalize bins that deviate significantly from the mean residual
    // to keep open bins at similar fill levels.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.1;

