        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // Global state adjustment: favor bins closer to the mean residual to keep distribution uniform.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

