    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // If this is a new bin (bin_residual == bin_capacity), apply a penalty 
    // that scales with progress, discouraging new bin creation late in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 + (50.0 * progress);
    }

    // Interaction with mean_residual: avoid bins that are significantly 
    // worse than the current average to maintain tight packing.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments (1-9)
    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward placements that leave a residual which is a multiple
    // of common item sizes or fits the next item perfectly.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

