    // unless the residual of the new bin is significantly better than current average.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (40.0 * progress) + (mean_residual * 0.5);
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, 
    // force its selection regardless of residual quality to preserve bin count.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. Residual Normalization: Prefer bins that maintain a residual close to the 
    // current mean to keep bin usage balanced (prevents "starving" bins).
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Strict dead space avoidance with bin-count pressure.
    // The goal is to minimize the creation of "orphaned" space (gaps < 10, the minimum item size)
    // while dynamically balancing the number of active bins.

    let mut score = post_residual as f64;

    // 1. PENALIZE DEAD SPACE: If the post_residual is smaller than the smallest possible item (10),
    // it is essentially wasted space. Exponentially penalize as it approaches 0.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powi(3);
    }

    // 2. OPEN BIN PRESSURE: If we are creating a new bin, penalize based on current open bin count.
    // This discourages opening new bins when many are already active, unless the fit is perfect.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 3. LOOKAHEAD COUPLING: If the next item exists, penalize the current placement if it 
    // prevents the next item from fitting into this specific bin.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 25.0;
    }

    // 4. FRAGMENTATION CONTROL: If this is the only bin that can fit the item, 
    // reward placing it here to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. MEAN RESIDUAL BALANCING: Favor bins that keep the bin's residual close to the
    // global mean to keep the packing density uniform across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score, so we favor tighter fits.
