    // Global state: if we have very few fitting bins, we are constrained.
    // Favor bins that leave a residual closer to the mean to maintain homogeneity.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // Criticality check: if this is the only bin that can fit the item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating 'dead space' (small residuals that are hard to fill later)
    // We penalize post_residual values that are smaller than the smallest possible item (10)
    // but larger than 0, as these often become unusable slivers.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.5;
    }

    // Lookahead coupling: If a next item exists, penalize bins that cannot fit it
    // after placing the current item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Adaptive thresholding: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid trailing waste in the final stages.
    let tightness_bonus = (1.0 - progress) * (post / bin_capacity as f64) * 10.0;
    score -= tightness_bonus;

    // Favor utilizing existing bins over opening new ones, but scale this 
    // preference by the density of existing bins.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty for opening new bins increases as we approach the end of the stream.
        score += 20.0 + (progress * 30.0);

        // If there are many fitting bins, heavily penalize opening a new one.
        score += (fitting_bins_count as f64) * 12.0;
    } else {
        // Existing bin: penalize if it's already very full (to keep space for large items)
        // or very empty (to consolidate).
        score += (mean_residual - post).abs() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
