    // 2. Lookahead: If the next item fits perfectly into the post_residual, reward this placement.
    // We aim for "Best Fit" but with a "Complementary Fit" bias.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Small penalty for leaving space slightly larger than the next item
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Heavy penalty if we kill the ability to fit the next item
            score += 20.0;
        }
    }

    // 3. Pressure management: If few bins can fit the current item, prioritize using them
    // to avoid fragmenting the remaining bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 4. Mean Residual alignment: Avoid bins that deviate significantly from the average
    // state, preventing "outlier" bins that are hard to fill later.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * residual_diff;

    // 5. Progression scaling: Be more aggressive about packing tightly towards the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
