    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early in the stream.
        score = 45.0 + (progress * 20.0);

        // If fitting_bins_count is 0, we MUST open a new bin.
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero 
    // to discourage "fragmentation" that cannot fit typical items (10-80 range).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice 
    // to preserve room for the upcoming item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the ones 
    // that are already closer to capacity to consolidate space.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 4. Thresholding: If this is the only bin that fits the item, reward it significantly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. New Bin Logic: If the bin is brand new, set a baseline cost that makes it 
    // unattractive unless existing bins provide poor fit potential.
    if bin_residual == bin_capacity {
        score = 45.0; 
        // Penalize opening a new bin if we haven't exhausted existing options
        score += (open_bins_count as f64) * 0.5;
    }

    // 6. Harmonic Class Logic: Favor residuals that align with common item size increments (10s)
    // to keep bins "clean" for future items.
    let remainder = post_residual % 10;
    score += (remainder as f64) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
