    let deviation = (post_residual as f64 - 25.0).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base Score: The post_residual represents wasted potential in the bin.
    let mut score = post_residual as f64;

    // 2. Penalty for creating a "Fragment": A bin with very small residual is hard to fill later.
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead Matching: If the next item fits perfectly into the remaining space, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward configurations that leave exactly 0 or very little space for the next item.
        score -= (30.0 - diff).clamp(0.0, 30.0);
    }

    // 4. Mean Residual Balancing: Avoid bins that deviate significantly from the average state.
    // This helps keep bin fullness uniform.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // 5. New Bin Penalty: Discourage opening new bins unless the fit is exceptionally poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is very low (bins are full)
        // or if we have very few open bins.
        score += 40.0;
        if mean_residual > 20.0 {
            score -= 20.0;
        }
    }

    // 6. Urgency: If this is the only bin that can fit the item, prioritize it to avoid new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 7. Progression Scaling: As the stream nears the end, prioritize tight packing (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
