    // 4. Global State Balancing: If we have many open bins, prioritize closing them (using existing ones).
    // If fitting_bins_count is low, we are running out of options to fit the item in existing bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0; // Strong incentive to use the last possible bin
    }

    // 5. Dynamic Threshold for New Bin Creation:
    // When bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only open a new bin if the progress is early or if existing bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation_penalty = if mean_residual < 15.0 { 40.0 } else { 10.0 };
        score += fragmentation_penalty + (progress * 10.0);
    }

    // 6. Mean Residual Correction: Avoid creating bins that deviate significantly from the average state.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
