            score -= (next_item_size as f64) * 1.5;
        } else {
            // If it creates a fragment too small for the next item, penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 4. Global balance: If this bin's residual is significantly lower than the mean, 
    // it is an efficient bin. Prefer keeping it tight.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression awareness: As the stream nears the end, become more conservative
    // to avoid leaving too many bins half-empty.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
