    }

    // 4. Efficiency incentive: Favor bins that become "tight" (post_residual near 0).
    // This effectively implements a Best-Fit-Decreasing behavior.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // 5. Fitting constraint: If this is the last chance for the current item, 
    // prioritize it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
