    // Incorporate mean_residual to favor bins that are already "fuller" (Best Fit approach).
    // This helps keep the variance of residuals low.
    let density_balance = (post - mean_residual).abs() * 0.2;

    // Final score: prioritize lowest post_residual (Best Fit) adjusted by the penalties/rewards.
    post + dead_space_penalty + lookahead_reward + new_bin_penalty + density_balance
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
