    // 3. Density Balancing: Prefer bins closer to the current mean residual
    // This keeps bins filled to similar levels, preventing "fragmentation"
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. New Bin Thresholding
    // If bin_residual == bin_capacity (New Bin Candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is large or we have many open bins already
        // This discourages opening new bins when space is available
        if item_size < 50 && open_bins_count > 0 {
            score += 45.0; 
        } else {
            score += 20.0;
        }
    }

    // 5. Urgency: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Modulo Harmonic Coupling:
    // Prefer post_residuals that are multiples of 20 (frequently compatible with distribution)
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

