    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // Dynamic adjustment based on stream progression
    // As we approach the end of the stream, prioritize aggressive packing (lower residuals)
    // Early on, allow more flexibility to avoid packing fragmentation
    score *= 1.0 + (0.5 * (1.0 - progress));

    // If this is a new bin, apply a heavy barrier cost that decays as the stream progresses
    // This forces the algorithm to use existing bins unless the fit is truly abysmal
    if is_new_bin {
        score += (bin_capacity as f64 * 0.8) * (1.0 - progress * 0.5);
        // If we have many open bins, penalize opening a new one further
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Reward bins that bring the mean residual closer to a target density (e.g., 10%)
        // This encourages "tight" bins over "loose" ones
        let density_error = (post_residual as f64 - 10.0).abs();
        score += density_error * 0.2;
    }

    // Lookahead influence: If the next item is large, favor bins that can still fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // If this is the last chance to fit the item in existing bins, significantly lower the score
    // to prevent opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
