    } else {
        // If it's an existing bin, reward it for reducing the count of open bins
        // by filling up effectively.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Fitting Constraint: If this is the only bin that fits the current item, 
    // make it highly attractive to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Mean Residual Balancing: Avoid bins that deviate significantly from the mean 
    // to keep the packing "level" across the bin set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual)
    // 2. Penalty for opening new bins: Only if no other good options exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0; // Heavy penalty for opening a new bin prematurely
    }

    // 3. Lookahead Matching: Reward bins that can perfectly accommodate the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // High reward for perfect future fit
        } else if post_residual > next_item_size {
            // Reward bins that remain "useful" for the next item
            score -= 10.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
