            score += 5.0;
        }
    }

    // 4. Density Balancing: Favor bins that stay close to the mean_residual of the system
    // This discourages creating "islands" of very small or very large residuals
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * deviation;

    // 5. Critical Constraint: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid wasting space in a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progressive tightening: As the stream nears the end, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
