    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalize the new bin significantly to prefer existing space, 
    // but allow it to become viable if current bins are nearly full
    if is_new_bin {
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // Penalty for creating a "fragmented" bin (residual too small for future items)
        // We use a non-linear penalty for residuals below 20 (assuming min item size ~10-20)
        if post_residual < 20 {
            score += (20.0 - post_residual as f64).powf(1.5);
        }

        // Lookahead: If the next item is large and won't fit in this residual, 
        // penalize this placement to keep space for the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
