    // Dynamic pressure: As the stream nears the end, become more aggressive 
    // about filling existing bins to avoid leftover bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 - progress);
    }

    // Factor in the global state: if we have too many open bins, penalize non-filling moves
    score += (open_bins_count as f64 * 0.5) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

