    // Based on the observation that items are >= 10, residuals < 10 are effectively dead.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Class Logic: Prefer residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This helps maintain "packability" for the next step.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 3. Lookahead integration: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Density management: Prefer bins that stay closer to the global mean residual.
    // This prevents creating too many sparse bins early on.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Thresholding: If this is the only bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 6. New bin penalty: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Add a significant cost to opening new bins unless the current best fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 7. Progression scaling: As the stream nears the end, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
