pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (fragments)
    // if they don't accommodate the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            // Reward placements that leave a residual perfectly sized for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 2. Bin Consolidation: If this is the last chance to fit the item in existing bins,
    // strongly favor the existing bin over starting a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 3. Fragmentation avoidance: Penalize bins that would end up with a residual 
    // that cannot fit even the smallest items (assuming lower bound 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Distribution balancing: Use the mean residual to keep bin fill levels consistent.
    // If this bin is much emptier than average, it's a candidate for consolidation.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 5. New Bin penalty: The "New Bin" call has bin_residual == bin_capacity.
    // We add a significant cost to open a new bin unless the existing ones are "tight".
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 50)
    // to keep the bin state "clean" for future items.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize "sliver" gaps (1-9) that are 
    // too small for most items, while balancing the creation of new bins.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the remaining space is too small to fit the smallest expected items (10),
    // it is highly likely to become permanent "dead space". We penalize these slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead awareness: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Bin count pressure: If we are choosing between a new bin and an existing bin,
    // we want to discourage opening new bins unless the existing fit is truly terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin is proportional to the number of bins already open.
        score += 25.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Reward using existing bins, especially if they are already "filled" (low residual).
        // If fitting_bins_count is 1, this is the last chance for this item in current bins.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // 4. Global distribution pressure: If the current bin's residual is significantly 
    // better than the mean, prioritize it to keep the average utilization high.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
