    // Base score is the post-placement residual (Best Fit principle).
    // Lower residual = tighter packing.
    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (unusable space < 10 units)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: If next item fits in the remaining space, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Dynamic constraint: If we are near the end of the stream, prioritize aggressive packing.
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    // Heuristic for New Bin:
    // Only open a new bin if the current fit is poor (post_residual > 20)
    // and we have many open bins already (to avoid fragmentation).
    if is_new_bin {
        if fitting_bins_count == 0 {
            // Must open a new bin.
            score = -50.0;
        } else {
            // Penalize opening a new bin if an existing bin could fit the item well.
            // Scale penalty by mean_residual to discourage opening bins when others are nearly empty.
            score = 100.0 + (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
        }
    } else {
        // If it's an existing bin, reward bins that are already "half-full" to keep others empty.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // Final adjustment: Penalize opening a new bin if the item is large
    // and we could have fit it into a bin with a better post_residual.
    if is_new_bin && item_size > 50 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Progression factor (0.0 to 1.0)
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Base score: prioritize smaller post_residual (Best Fit principle)
    // We use a power-based penalty for post_residual to favor tight packing
    let mut score = (post_residual as f64).powf(1.5);

    // Penalty for creating a new bin: if this bin is currently empty (bin_residual == bin_capacity)
    // We increase the cost of opening a new bin as the stream progresses to consolidate packing.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is 50.0. We scale it up by progress to discourage
        // opening new bins late in the stream if existing bins are available.
        score += 50.0 + (progress * 150.0);
    }

    // Lookahead logic: Reward bins that can accommodate the next item (k=2)
    // If next_item_size fits in the post_residual, reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.2;
    }

    // Heuristic coupling: If this is the last bin that can fit the item, 
    // prioritize it to avoid fragmenting open bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global density normalization:
    // If we have many open bins, penalize larger post_residuals more aggressively
    // to force convergence toward full bins.
    score += (open_bins_count as f64) * (post_residual as f64) * 0.1;

    // Penalty for leaving space that is smaller than the average residual
    // (Fragmented space is usually useless)
    if (post_residual as f64) < mean_residual {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "unusable" small gaps (1-9) which are often impossible to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Harmonic preference: reward bins that leave residuals which are multiples of common item sizes
    // This aligns with bin-packing "Best Fit" but adds a lookahead penalty
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for keeping a bin "ready" for the next item
            score -= 30.0;
        } else {
            // Penalty for stranding the next item if this was the last viable bin
            if fitting_bins_count == 1 {
