    }

    // Dynamic thresholding based on stream progression
    let progress = step_index as f64 / total_items as f64;

    // If we are late in the stream, prioritize aggressive consolidation (lower residual)
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    // New bin logic: only open a new bin if the current post_residual creates a "dead zone"
    // or if the current mean_residual is already very low (indicating fragmentation).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // Penalty for opening a new bin prematurely
            score += 60.0;
        } else {
            // Baseline cost for opening a new bin
            score += 35.0;
        }
    }

    // Harmonic class penalty: avoid residuals that are "near miss" to 50% capacity
    // as they often lead to stranded space.
    let diff_from_half = (post_residual as f64 - 50.0).abs();
    if diff_from_half < 5.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small, unusable gaps.
    // If post_residual is < 10, it is likely unusable for future items.
    if post_residual > 0 && post_residual < 10 {
