    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // 5. Mean Residual Balancing: Penalize bins that deviate too far from the average state.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
