        score = 85.0 + (100.0 - (item_size as f64));

        // If there are other bins that could fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 5. Mean-residual balancing:
    // Prefer bins that stay close to the current mean residual to maintain uniform bin state.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
