        }
    }

    // 4. Tightness bias: If this is the only fitting bin, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Mean residual equilibrium: Penalize bins that deviate significantly from the mean residual
    // to keep bins packed at similar levels.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // If this is a new bin (residual == capacity), penalize it based on how many
    // existing bins could have taken the item.
    if bin_residual == bin_capacity {
        score += 45.0 + (fitting_bins_count as f64 * 5.0);
    }

    // 2. Aggressive 2-step lookahead matching:
    // If a future item exists, prioritize bins where the post_residual is close
    // to the next_item_size, effectively favoring "perfect" future fits.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward bins that can accommodate the next item exactly
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.3;
        } else {
            // Penalize creating a bin that cannot take the next item if it's large
            score += next_item_size as f64 * 0.5;
        }
    }

    // 3. Efficiency heuristic:
    // Penalize bins that leave behind "dead space" (small residuals that are hard to fill).
    // Specifically, residuals < 10 are often unusable for the given item range.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // 4. Global state balancing:
    // If the mean residual is high, we are being too loose; prioritize tighter fits.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression adjustment:
    // Toward the end of the stream, prioritize aggressive consolidation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
