            // Baseline for when we have no choice
            score = 40.0;
        }
    } else {
        // 4. Balance the packing: favor bins that are already partially filled 
        // to keep the number of active bins low.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // 5. Late-stage heuristic: Be more aggressive in packing as we approach the end
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
