    // Favor bins that align with the global mean residual to keep bin states uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.2;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy 
    // start-up cost that decays as the stream nears the end, but stays high
    // enough to force Best Fit behavior.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - (progress * 0.2));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // Base score is already post_residual.

    // 2. Harmonic/Modulo Penalty: Penalize residuals that are likely to become 'dead space'.
    // If post_residual is small but > 0, it often prevents larger items from fitting later.
    if post_residual > 0 && post_residual < 20 {
