            // Reward opening a new bin if no other bins fit
            score -= 20.0;
        }
    }

    // 5. Global state normalization:
    // As the stream progresses, favor packing bins tighter to reduce the 
    // total number of bins toward the end.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 15.0);

    // 6. Balance against mean_residual:
    // If this bin's post_residual is significantly better than the global mean,
    // boost its priority.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tight.
    // 2. Dead-space avoidance: If post_residual is in (0, 10), it's likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 4. Scarcity/Global State: If bins are scarce, prioritize packing tightly.
    // We normalize the open_bins_count against progress to avoid opening bins too early.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // 5. New Bin Logic: Discourage opening a new bin unless the remaining open bins 
    // are poorly suited for the current or next item.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score += 40.0;
        // If we have other options, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
        // If the item is large, opening a new bin is less penalized.
        score -= (item_size as f64) * 0.5;
    }

    // 6. Mean Residual Balancing: Avoid deviating too far from the average state.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post;

    // Penalty for leaving small, unusable gaps (1..10)
    // We penalize post_residual values that are likely to be "dead zones"
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 / (post + 0.1));
    }

    // Lookahead logic: If a future item exists, prioritize bins that can accommodate it
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 15.0; // Reward bins that keep the next item packable
        }
    }

    // Dynamic pressure: As the stream progresses, become more aggressive 
    // in filling bins to minimize the total count (Best Fit vs New Bin trade-off)
    // We add a scaling factor based on the number of open bins to encourage consolidation
    let density_pressure = (open_bins_count as f64) * progress;
    score += density_pressure * 2.0;

    // Interaction term: Penalize bin selection if it deviates significantly from the mean residual
    // This promotes uniform filling across all active bins
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    // Critical New Bin logic:
    // If this is a new bin (res == capacity), penalize it heavily early on,
    // but allow it if no other bins can fit the item (fitting_bins_count == 0)
    if res == bin_capacity as f64 {
        if fitting_bins_count > 0 {
            score += 50.0 + (50.0 * (1.0 - progress));
        } else {
            score -= 10.0; // Necessary evil: opening a new bin is better than failing
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize fragmentation: If the post_residual is small but > 0, it creates "dead space" 
