    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item could fit into the current post_residual,
    // we want to prioritize this bin. We apply a discount for "future-proofing".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // 3. Harmonic class bias: Favor bins that leave a residual which is a multiple of 10 
    // or aligns with common item size distributions (modulo arithmetic).
    let harmonic_penalty = (post_residual % 10) as f64 * 1.5;
    score += harmonic_penalty;

    // 4. New bin management: If this is a new bin (residual == capacity), 
    // penalize it unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
