    // that would force a new bin for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // 3. Open Bin Pressure: Penalize opening new bins unless the current fit is 
    // extremely poor or we are near the end of the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual is already tight, 
        // to avoid fragmentation.
        score += (open_bins_count as f64 * 2.5) - (mean_residual * 0.5);
    } else {
        // Reward using existing bins, but apply a penalty if the fit is loose 
        // compared to the global mean (Best-Fit style).
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, 
    // heavily incentivize choosing it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
