pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that create "dead space" (e.g., < 10) unless it's a perfect fit
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Reward bins that keep the mean residual balanced
    let balance_factor = (post - mean_residual).abs() * 0.5;

    // Lookahead: If next_item_size is large, prefer leaving a larger post_residual
    // We penalize tight fits if a large item is coming next
    let lookahead_penalty = if next_item_size > 60 && post < (next_item_size as f64) {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Transition logic: As the stream nears the end, become more aggressive about 
    // packing tightly (Best Fit) to close out bins.
    let tightness_weight = 1.0 + (progress * 5.0);

    // If bin_residual == bin_capacity, we are evaluating opening a NEW bin.
    // We only want to open a new bin if the existing options are very poor.
    let new_bin_base_cost = if bin_residual == bin_capacity {
        // High cost to open a new bin, but reduce as we near the end to clear remaining items
        45.0 - (progress * 15.0)
    } else {
        0.0
    };

    // Combine factors
    // Lower score is better.
    let score = (post * tightness_weight) 
        + dead_space_penalty 
        + balance_factor 
        + lookahead_penalty 
        + new_bin_base_cost;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
