    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: If this bin is the last one that can fit the item, 
    // we heavily reward placing it here to avoid opening a brand-new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. Global efficiency: Favor bins that keep the mean residual of the system low.
    // If this bin's post_residual is lower than the current mean, it's a good candidate.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. New Bin Penalty: If the bin is new, apply a base penalty proportional to the 
    // number of bins already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Progressive scaling: As the stream nears completion, prioritize packing 
    // tightly to finish the remaining items in existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want to minimize post_residual, so it stays as the baseline.

    // 2. Lookahead Synergy: Reward bins that can fit the next item perfectly (or close to it)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
