    // 3. New Bin Thresholding: Prevent premature new bin opening
    // Only open a new bin if the residual is extremely poor or if we are forced
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // High penalty for opening a new bin if existing ones can fit the item
            score += 90.0;
        } else {
            // Base cost for opening a new bin
            score += 10.0;
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly from the mean
    // This helps keep the bin distribution uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * deviation;

    // 5. Packing Density Incentive: Reward filling bins that are already tight
    if bin_residual < 30 {
        score -= 15.0;
    }

    // 6. Last Chance Logic: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
