        score -= 15.0;
    }

    // 5. Balance bin usage: If mean_residual is high, we are under-utilizing bins.
    // Penalize bins that increase the mean_residual significantly.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early in the stream, but allow flexibility near the end.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Use post_residual to favor tight fits (Best-Fit principle).
    // Square the post_residual to penalize "wasted" space exponentially.
    let fit_score = post * post / 100.0;

    // Lookahead logic: if next item is large, avoid leaving a bin with a small residual that is hard to fill.
    // If next_item_size is 0, we are at the end, so prioritize closing bins.
    let lookahead_penalty = if next_item_size > 0 && (post < next_item_size as f64) {
