    };

    // Coupling: If this is the last chance for the current item (fitting_bins_count == 1),
    // reduce the penalty for a poor fit to avoid opening a new bin unnecessarily.
    let urgency_factor = if fitting_bins_count == 1 && !is_new_bin {
        -20.0
    } else {
        0.0
    };

    fit_score + new_bin_penalty + lookahead_penalty + urgency_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
