    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the mean residual of current bins is high (high fragmentation)
        // or if there are no bins that can fit the item well.
        score += 45.0 + (mean_residual * 0.5);
        if fitting_bins_count > 0 {
