    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We increase the cost of opening a new bin linearly with progress to prevent fragmentation.
    let new_bin_cost = if bin_residual == bin_capacity {
        40.0 + (progress * 60.0)
    } else {
        0.0
    };

    waste_penalty + leveling_factor + lookahead_bias + scarcity_factor + new_bin_cost
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual
    // We already start with post_residual, so smaller is better.

    // 2. Harmonic Class Penalization:
    // If the post_residual is small but not zero, it creates "dead space".
    // Penalize values that are difficult to fill (e.g., small remainders < 15).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 3. Lookahead Synergy:
    // If we have a next item, check if the current post_residual can accommodate it.
    // If it fits perfectly or leaves little waste, heavily reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            // If it doesn't fit the next item, penalize proportionally to the wasted gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 4. Threshold Management:
    // If this is the last chance bin (fitting_bins_count == 1), we are forced to use it.
    // We make it slightly more attractive to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // 5. New Bin Control:
    // When bin_residual == bin_capacity, we are evaluating a brand new bin.
    // Penalize opening a new bin heavily unless the open bins are "clogged" 
    // (i.e., mean_residual is very low).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 50.0; // Heavily discourage new bin if existing ones have space
        } else {
            score += 15.0; // Baseline cost for opening a new bin
        }
    }

    // 6. Progression Bias:
    // As the stream nears the end, prioritize closing out bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

