    } else {
        // Favor bins that are already open and have a residual closer to the mean 
        // to maintain balance across the bin set.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 4. Scarcity adjustment: If this is the last bin that can fit the item,
    // reduce the penalty for a poor fit to ensure the item is packed.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
