    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 5. Fitting Context: If this is the only bin that fits the current item,
    // we heavily prioritize it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 6. New Bin Penalty: Make opening a new bin expensive unless necessary.
    // If bin_residual == bin_capacity, it's a new bin candidate.
    if bin_residual == bin_capacity {
