            score -= 100.0; // Must open if no bins exist
        } else {
            // Only open a new bin if the mean residual of existing bins is already very tight
            // or if we have many bins and need to start fresh.
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // 7. Balance the number of open bins:
    // Penalize having too many bins open (fragmentation).
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "slivers" (dead space < 10)
    // We penalize post_residual values in the [1, 9] range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_res + 1.0);
    }

    // Lookahead coupling: If a subsequent item fits perfectly into the resulting residual, 
    // reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 / (diff + 1.0));
    }

    // Dynamic density management:
    // As the stream progresses, favor packing tighter (lower mean_residual).
    // We add a term based on the deviation of this bin's post_residual from the current mean.
    score += (post_res - mean_residual).powi(2) * 0.1 * progress;

    // New bin avoidance:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with the number of existing bins and the progress of the stream.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0 * (1.0 - progress));
    }

    // If only one bin can fit the item, it is a "forced" fit. 
    // If it's a poor fit (large post_residual), we might prefer opening a new bin 
    // if the stream is early (progress is low).
    if fitting_bins_count == 1 && post_residual > 50 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
