        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Dynamic thresholding: If we are near the end of the stream, prioritize closing bins.
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            // Last resort: opening a new bin is necessary.
            score = 0.0;
        }
    }

    // Influence of global state: If current bin is significantly emptier than the mean, 
    // prioritize filling it to avoid spreading items too thin.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // Reward perfect fits (zero residual) heavily.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
