    // we reduce the score to prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
        // Further boost if this makes the bin nearly perfectly filled
        if (post_residual - next_item_size) < 5 {
            score -= 20.0;
        }
    }

    // 3. Mean Residual Balancing:
    // Avoid creating bins that are significantly "emptier" than the current average.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 4. Scarcity/Fitting heuristic:
    // If this is the only bin that can fit the item, prioritize it strongly
    // unless it results in a very poor fit.
    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 50.0;
    }

    // 5. New Bin Penalty:
    // If the bin is new (bin_residual == bin_capacity), penalize opening it
    // unless the fit is perfect or we have no other choice.
    if bin_residual == bin_capacity {
        score += 35.0; 
        // If the item is very large, it's safer to open a new bin than to ruin an existing one
        if item_size > 70 {
            score -= 25.0;
        }
    }

    // 6. Progress sensitivity:
    // As we approach the end of the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize creating small, unusable gaps (1..10) 
    // unless it is the very end of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0 * (1.0 - progress);
    }

