            score -= 10.0;
        }
    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly 
    // from the average to maintain uniform density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
