pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily, especially as the stream progresses, 
    // unless the current fit is extremely poor (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let base_penalty = if is_new_bin {
        // As we approach the end of the stream, opening a new bin is increasingly costly.
        // We modulate this by how many bins are already open to favor consolidation.
        50.0 + (open_bins_count as f64 * 2.0) + (progress * 50.0)
    } else {
        0.0
    };

    // Non-linear coupling: Prefer bins where post_residual is small (Best Fit).
    // However, if next_item_size is large, we penalize bins that would leave 
    // a residual just slightly too small to fit the next item (e.g., 10-15 space).
    let mut score = post.powf(1.5);

