    // strand space that cannot be used by the upcoming item.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 2.5;
    }

    // If this is the last bin that can fit the item, reward it to prevent 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Incorporate mean_residual to favor bins that are already "fuller" than average
    // to maintain a consistent fill level across the bin population.
    score += (post - mean_residual) * 0.5;

    score + base_penalty
}

