    // If post_residual is in the range (0, 10), it is highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 20.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, avoid leaving a residual that cannot fit it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0;
    }

    // 3. Open bins pressure: Discourage opening new bins unless the current fit is extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 15.0);
    }

    // 4. Efficiency normalization: Favor bins that align with the current mean residual to keep packing density uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Urgency: If fitting_bins_count is 1, we are at a bottleneck; prioritize the current bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // 6. Progressive packing: As the stream nears completion, tighten the constraints to force tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual)
    // The default score is the post_residual, which inherently encourages Best-Fit.

    // 2. Penalty for opening a new bin prematurely:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless there are no other viable options (fitting_bins_count == 0).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0; 
    }

    // 3. 2-Step Lookahead Matching:
    // If the post_residual is close to the next_item_size, we prioritize this bin
    // to create a "perfect" or near-perfect fit for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward bins that can accommodate the next item perfectly
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.4;
        } else {
            // Penalize bins that are too small for the next item
            score += 20.0;
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the mean residual of current bins.
    // This keeps the "tightness" of bins uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // 5. Progression awareness:
    // As we approach the end of the stream, prioritize filling existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 10.0;
