    }

    // 5. New bin logic: When bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only do this if the open bins are already too full to handle future items effectively.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost + pressure from existing empty space.
        score += 35.0 + (mean_residual * 0.2);
    } else {
        // If we are placing into an existing bin, reward configurations that bring 
        // the post_residual closer to the mean residual of other bins (load balancing).
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
