    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we approach the end of the stream.
        score += 10.0 + (progress * 40.0);
    }

    // 4. Fitting Density: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Mean residual balance: Avoid bins that deviate too far from the average state of open bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement (Best Fit strategy)
    let mut score = post;

    // Penalty for creating "slivers" (very small unusable gaps between 1 and 9)
    // We prioritize bins that leave 0 space or >= 10 space.
    if post > 0.0 && post < 10.0 {
        score += 20.0 + (10.0 - post) * 5.0;
    }

    // Lookahead logic: If a future item exists, reward bins that can accommodate it.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 15.0 * (1.0 - progress);
        } else {
            score += 5.0 * progress;
        }
    }

    // Dynamic thresholding: As the stream progresses, become more conservative about 
    // opening new bins (penalize empty bin selection increasingly).
    if bin_residual == bin_capacity {
        score += 30.0 + (40.0 * progress);
    }

    // Coupling: If we have many open bins, penalize opening a new one significantly.
    // If we have few open bins, favor filling existing ones to keep the footprint low.
    if fitting_bins_count == 0 {
        score -= 50.0; // Forced to open new bin
    } else {
        score += (open_bins_count as f64 * 0.5) * (1.0 + progress);
    }

    // Smooth non-linear adjustment based on how the current bin compares to the mean
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += (deviation / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
