    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 2. Encouraging pack density: Penalize deviations from the current mean residual
    // This promotes "bin leveling" to keep future options balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // 3. Last chance logic: If this is the only bin that can fit the item, we heavily prioritize it
    // to avoid opening a new bin unnecessarily (unless the fit is extremely poor).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. New bin penalty: If the bin is new (empty), apply a dynamic penalty based on the 
    // progression of the stream to favor packing into existing bins early on.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // As the stream progresses, we become more tolerant of opening new bins.
        score += 45.0 * (1.0 - progress);
    }

    // 5. Hard constraint: If the item doesn't fit, ensure it's not selected (or very high score).
    if item_size > bin_residual {
        score = 1e9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
