    // 3. Fragmentation avoidance: If this is the last fitting bin, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // 4. Harmonic Capacity Coupling: Penalize residuals that are non-multiples of common 
    // item sizes (e.g., 20, 25, 33) to favor future "clean" fits.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current mean residual 
