    // 4. Global Density Management:
    // If we have many open bins, prioritize filling the ones closest to the mean_residual
    // to keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is 0 or the current bin is truly terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing options
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other options, make it neutral
            score -= 10.0;
        }
    }

    // 6. Progressive Tightening:
    // As we reach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
