}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-residual space.
    // We aim to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating "slivers" (very small unusable gaps).
    // If post_residual is in (0, 10), it's likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // We penalize the current choice if it leaves less space than the next item requires.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: as the stream progresses, we become more aggressive about 
    // filling existing bins to reduce open_bins_count.
    let fill_pressure = (open_bins_count as f64) * progress;
    score += fill_pressure * (post / bin_capacity as f64);

    // If this is the only bin that fits, prioritize it heavily to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // If this is a new bin (residual == capacity), penalize it relative to the 
    // current efficiency (mean_residual). Only open if the cost of existing fits is high.
    if bin_residual == bin_capacity {
        score = 60.0 + (mean_residual * 0.5) - (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post_residuals that are small but non-zero (the "dead space" trap)
    // We favor exact fits (post_residual == 0) or large residuals.
    if post_residual > 0 {
        score += (bin_capacity as f64) / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
