    // 4. Global Consolidation: Reward bins that are already closer to the mean residual
    // to keep the distribution of remaining space uniform across bins.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Heavily favor tighter fits (lower post_residual).
    // The base score starts at post_residual.

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward the placement
    // because we create a bin that will likely be perfectly filled in the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
