        // 5. Urgency: If this is the only fitting bin, prioritize it to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Global progression adjustment: As the stream nears completion, 
    // become more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
