pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Penalize creating tiny, unusable gaps (1-9) which are hard to fill later.
    // We prioritize "perfect" fits (post == 0) and "spacious" fits (post > 10).
    let fragmentation_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large, favor bins that leave enough space for it.
    // If next_item_size is 0 (end of stream), prioritize closing bins (minimizing residual).
    let lookahead_alignment = if next_item_size > 0 {
        let needed = next_item_size as f64;
        if post >= needed {
