        }
    } else {
        post * 0.5
    };

    // Dynamic pressure: As the stream progresses, increase the cost of opening new bins 
    // to encourage consolidation.
    let new_bin_cost = if bin_residual == bin_capacity {
        25.0 + (progress * 50.0)
    } else {
        0.0
    };

    // Interaction with mean_residual: favor bins that keep the overall average residual low,
    // preventing the creation of "outlier" bins with high waste.
    let stability_bonus = (post - mean_residual).abs() * 0.2;

    // Final score assembly:
    // We minimize this score. 
    // - Low post_residual is usually good (Best Fit), but we apply penalties for "dead zone" fragments.
    // - Incorporate the lookahead to avoid blocking future large items.
    post + fragmentation_penalty + lookahead_alignment + new_bin_cost + stability_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
