    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low
        // or if we have very few options to fit the current item (high fragmentation)
        let new_bin_base_cost = 45.0; 
        score = new_bin_base_cost + (mean_residual * 0.5);
    } else {
        // If it's the last chance to fit an item, reduce the score to encourage taking it
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We prioritize bins that result in smaller residuals (tighter packing)
    score += (post_residual as f64) * 0.5;

    // 2. Harmonic/Modulo Penalty: Avoid creating "fragmented" residuals that are hard to fill.
    // If post_residual is small but not zero, it's often a "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead logic: If a bin can fit the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Strategic New Bin Opening:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless the current 
    // fitting_bins_count is low or the current bins are very full (low mean_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Necessary to open new bin
        } else {
            // Discourage opening a new bin if we have plenty of open bins
            score += 60.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 5. Reward bins that are already "half-full" to keep them active
        // This is a variation of the Best-Fit Decreasing heuristic principle.
        let usage = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= usage * 15.0;
    }

    // 6. Progressive scaling: As we approach the end of the stream, 
    // force tighter packing by increasing the penalty for large residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are too small to fit common items
    // (1..10 range is extremely difficult to fill, 10..20 is suboptimal).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    } else if post_residual >= 10 && post_residual < 20 {
