            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // Reward filling existing bins to keep open_bins_count low
        score -= (open_bins_count as f64) * 0.5;
    }

    // 4. Perfect Fit Bonus: Strongly prioritize zero-residual bins to clear them out
    if post_residual == 0 {
        score -= 60.0;
    }

    // 5. Fitting Constraint: If this is the last bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bin allocation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
