    // 3. New Bin Thresholding: Discourage opening a new bin unless the current fit is poor.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing options are very poor (high post_residual).
        // Or if we are approaching the end of the stream and need to consolidate.
        score += 45.0; 
        score -= (step_index as f64 / total_items as f64) * 10.0;
    }

    // 4. Mean Residual Balancing: Avoid creating bins that are significantly "emptier" than the average.
    // This maintains a uniform distribution of fill levels across bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We want the smallest post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We define "dead" as < 15, as items are >= 10.
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // Lookahead logic: If we have a next item, check if it fits in the current post_residual.
    // If it fits perfectly, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // If it doesn't fit, penalize based on how much "wasted" potential the bin has.
            score += 10.0;
        }
    }

    // Dynamic thresholding: discourage opening new bins as we approach the end of the stream.
    if is_new_bin {
        // High base penalty for new bins, scaled by progress and open bins
        score += 35.0 + (progress * 20.0) + (open_bins_count as f64 * 0.5);
    } else {
        // Encourage using existing bins if they are already packed well (near the mean)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Criticality check: If this is the only bin that fits the item, make it extremely attractive
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small slivers (dead space) that are too small for common items (10-30)
    // The penalty is modulated by progress: we are more conservative toward the end of the stream
    let sliver_penalty = if post < 20.0 && post > 0.0 {
        (20.0 - post) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Reward bins that bring the residual closer to the mean of other bins (load balancing)
    let balance_penalty = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: if the next item is large, favor bins that leave enough room for it
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // If this is a new bin, penalize it relative to how many bins are already open
    // but reduce this penalty as we approach the end of the stream to favor packing efficiency
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 5.0) * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Base score is the post_residual (Best-Fit principle)
    // We add penalties to push the choice away from inefficient spots
    let mut score = post + sliver_penalty + balance_penalty + lookahead_penalty + new_bin_penalty;

    // If only one bin fits, force it by lowering the score significantly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments (1-9)
    // which are difficult to fill later, unless we are nearing the end of the stream.
    if post_residual > 0 && post_residual < 10 {
        let progress = step_index as f64 / total_items as f64;
        score += (10.0 - post_residual as f64) * (1.0 + 5.0 * (1.0 - progress));
    }

    // 2. Harmonic Class Logic: Reward residuals that align with common item sizes.
    // If post_residual is a multiple of 20, it is more likely to fit future items.
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 3. Lookahead Integration: If the next item fits into the current post_residual,
    // prioritize this bin to prevent fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further favor tight fits for the lookahead item
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // 4. Open-Bin Pressure: If only one bin can fit the item, we are forced to use it.
    // Otherwise, penalize opening new bins unless the residual is very poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // New bin is expensive if we have options
            score += 50.0;
        } else {
            // New bin is necessary
            score -= 10.0;
        }
    }

    // 5. Global Mean Alignment: Avoid bins that deviate significantly from the mean
    // to keep the bin distribution uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
