    }

    // 4. Global Density Awareness: Compare current bin_residual to the global mean.
    // If this bin is significantly emptier than the average, we prefer filling it.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0 * (bin_residual as f64 / mean_residual);
