        // Penalize opening a new bin heavily unless open_bins_count is low or 
        // current fitting options are extremely poor (i.e., would result in high post_residuals).
        score = 85.0 + (open_bins_count as f64 * 0.5);
    } else {
        // 2. Harmonic Class Logic:
        // Penalize residuals that cannot easily accommodate common item sizes.
        // We use the post_residual to check if it creates a "dead zone" for future items.
        let penalty_for_dead_space = if post_residual < 10 {
            -20.0 // Reward tight fits (near-zero waste)
        } else if post_residual < 20 {
            5.0   // Mild penalty for small unusable slivers
        } else {
            (post_residual as f64) * 0.2
        };

        // 3. Lookahead Integration:
        // If next_item_size is large, favor bins that can accommodate it.
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
            -15.0 // Strong incentive to keep space for the next item
        } else if next_item_size > 0 && post_residual < next_item_size {
            10.0  // Penalty for creating a bin that cannot fit the next item
        } else {
            0.0
        };

        // 4. Global Density Awareness:
        // As the stream progresses, prioritize closing bins (lower score) to clear space.
        let progress = step_index as f64 / total_items as f64;
        let density_factor = (mean_residual - post_residual as f64) * progress;

        score += penalty_for_dead_space + lookahead_bonus - density_factor;
    }

    // 5. Fitting Constraint: 
    // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
