    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) 
    // especially early in the stream, to encourage consolidation.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (1.0 - progress) * 100.0);

    // Best-Fit Decreasing logic: minimize post_residual, 
    // but penalize very small residuals (e.g., < 5) as they create "dead" space 
    // that cannot fit subsequent items (min size 10).
    let dead_space_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powf(2.0) * 5.0
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size exists, penalize bins that 
    // would be unable to fit it after the current placement.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Global state weighting: Favor placing in bins that align with the 
    // global mean residual to keep bin fullness uniform.
    let mean_alignment = (post - mean_residual).abs() * 0.5;

    // Final score: minimize this value.
    // Base score is post_residual (smaller is better).
    post + new_bin_penalty + dead_space_penalty + lookahead_penalty + mean_alignment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
