    // This encourages keeping bin residuals uniform for better future fitting
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Prefer filling bins that are already "half-full" or more to clear them out
    if bin_residual < (bin_capacity / 2) {
