    // 3. Open bins pressure: Discourage opening new bins unless necessary (fitting_bins_count == 0).
    // If the bin is new (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by the current number of open bins to encourage consolidation.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong discouragement for opening a new bin if an existing one works.
            score += 200.0 + (open_bins_count as f64 * 5.0);
        } else {
            // Neutral penalty for mandatory new bin.
            score += 10.0;
        }
    }

    // 4. Prefer bins that keep the mean residual low (Best Fit variation).
    // We want the bin that, after placement, is as close to full as possible.
    // The base score (post_residual) already favors this, but we add a tie-breaker
    // against bins that are significantly below the current mean.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more aggressive
    // about fitting items into existing bins (minimizing total bins used).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
