pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We prioritize Best-Fit (minimizing post_residual) but penalize "fragmentation" 
    // where post_residual is too small to fit likely future items.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals between 1 and 9).
    // These are often unusable given the item range (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If the next item can fit in the current post_residual, 
    // reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Harmonic/Modulo pressure: Penalize residuals that are poor divisors 
    // of the capacity relative to the mean_residual.
    let residual_utilization = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score += (residual_utilization * 10.0);

    // 4. If this is the only bin that can fit the item, prioritize it to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. If considering a new bin (bin_residual == bin_capacity), apply a heavy 
    // penalty based on the number of bins already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.0);
        // If we still have plenty of room in other bins, discourage opening new ones.
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 30.0;
        }
    }

    // 6. Progression-based scaling: As we near the end of the stream, 
    // prioritize tighter packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base heuristic: prioritize tightness (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for creating "unusable" dead space (gaps < 10 are rarely useful for items >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic for new bins: Only open a new bin if the current fit is extremely inefficient 
    // or if we have very few bins open (to avoid fragmentation later).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -10.0; // Always open the first bin
        } else {
            // Penalize opening a new bin: only do it if the average residual is already high,
            // or if we are nearing the end of the stream and need to clear out open bins.
            score += 45.0 + (mean_residual * 0.5) + (progress * 20.0);
        }
    }

    // Lookahead: If next_item_size is large, prefer bins that leave enough room for it
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // Penalize bins that would "starve" the next item
            score += 25.0;
        } else {
            // Reward bins that can accommodate the lookahead item
            score -= 15.0;
        }
    }

    // Pressure factor: if there are many open bins, prioritize filling them to reduce active count
    score += (open_bins_count as f64) * 0.5;

    // If this is the only bin that can fit the item, prioritize it heavily to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize leaving 
    // small slivers (e.g., 1-9) which are statistically harder to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post-placement
    // gap, heavily favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward configurations that leave exactly 0 or very little space for the next item
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Global Efficiency: If the bin is a new bin, penalize it relative to the 
    // current mean_residual to prevent premature expansion.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.8;
        // If other bins could fit the item, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Critical Thresholding: If this is the last chance to fit the item in existing bins,
    // reduce the penalty for poor fits to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression adjustment: As the stream nears completion, prioritize closing
    // bins (lower post_residual) to reduce overall bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space to favor tight packing.
    // Higher post_residual is penalized to keep bins full.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: If next_item_size is known, penalize placements 
    // that make it impossible to fit the next item in this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0; // Reward keeping the next item in the same bin
    }

    // 3. Last-chance protection: If this is the only bin that can fit the current item, 
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // 4. New bin thresholding: Penalize opening a new bin unless the current 
    // packing efficiency (mean_residual) is already very poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins open already or if we are 
        // nearing the end of the stream and need to clear out remaining items.
        score += 40.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    // 5. Fragmentation control: If the post_residual is small (e.g., < 10), 
    // it is likely "dead space". Penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res_f = bin_residual as f64;

    // Penalize opening a new bin heavily unless we are in the late stages (progress -> 1.0)
    // where packing tightly becomes less critical than minimizing total bin count.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = if is_new_bin {
        (1.0 - progress) * 200.0 + (open_bins_count as f64 * 5.0)
    } else {
        // Best Fit Decreasing logic: reward smaller post_residual.
        // We use a non-linear penalty for large post_residuals to avoid fragmentation.
        post_res.powf(1.5)
    };

    // Lookahead coupling: if the next item fits into the current post_residual,
    // apply a significant discount to favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0 * (1.0 + progress);
    }

    // Heuristic pressure: if this is the only bin that fits the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // Global load balancing: penalize bins that deviate too far from the mean residual
    // to keep bins roughly equal in fullness, reducing the variance of future fit chances.
    let dev = (res_f - item_size as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize minimizing post_residual (the base score).
    // 2. Penalty for creating "dead space": if post_residual is in the range [1, 9], 
    //    it is highly likely to be unusable for future items (sizes 10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead synergy: if the next item fits into the post_residual, 
    //    heavily reward this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Harmonic class pressure: discourage leaving bins that are exactly 
    //    half-full (50), as they often create fragmentation.
    if post_residual > 45 && post_residual < 55 {
        score += 15.0;
    }

    // 5. Threshold management: If this is the only bin that fits, 
    //    prioritize it over opening a new bin (fitting_bins_count == 1).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. New-bin thresholding: only open a new bin if the residual capacity 
    //    is significantly better than existing options. 
    //    If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, adjusted by current progress
        // to encourage tighter packing as the stream concludes.
        let progress = step_index as f64 / total_items as f64;
        score = 35.0 + (progress * 10.0);
    }

    // 7. Global balance: penalize opening too many bins relative to the mean residual.
    if open_bins_count > 0 {
        score += (open_bins_count as f64 * 2.0) - (mean_residual * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

