    // Residuals between 1 and 9 are extremely difficult to fill given the input distribution (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open bin pressure: 
    // If the bin is new (bin_residual == bin_capacity), penalize it based on how many
    // bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have many open bins, prioritize packing into existing ones unless 
