    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin with very small residual (under 10), 
    // as it creates "dead space" that is hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bin that can fit the next item
        } else if post_residual > 0 {
            score += 10.0; // Penalize bin that will likely force a new bin for the next item
        }
    }

    // Global state optimization:
    // If we have many open bins, prioritize filling the ones with the smallest residuals (Best Fit)
    // to keep the number of active bins low.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // New bin logic:
    // Only open a new bin if the residual of existing bins is already quite tight,
    // or if we are nearing the end of the stream and need to pack efficiently.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 40.0;

        // As the process nears completion, opening a new bin is heavily penalized
        score += progress * 60.0;

        // If other bins can fit the item, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // Non-linear coupling: penalize small residuals that are too small to fit future items 
    // but large enough to waste space (the "dead zone" ~ 5-15).
    let mut score = post * (1.0 + 0.5 * (10.0 / (post + 1.0)).exp());

    // Penalty for opening a new bin:
    // If we are looking at a new bin (bin_residual == bin_capacity), 
    // apply a significant penalty that decreases as the stream progresses (to allow flexibility at the end).
    if bin_residual == bin_capacity {
