    }

    // Lookahead logic:
    // If the next item is large (e.g., > 50), reward bins that currently have enough 
    // post_residual to accommodate it, effectively "saving" space for the next item.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 15.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Fitting density awareness:
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global state awareness:
    // Penalize increasing the number of bins if the average residual is already high,
    // encouraging consolidation.
    score += (open_bins_count as f64) * (1.0 - (mean_residual / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
