    // 1. Best-Fit logic: penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo logic: reward post_residuals that are multiples of common item sizes
    //    to minimize fragmentation.
    let remainder_penalty = (post_residual % 10) as f64 * 0.5;
    score += remainder_penalty;

    // 3. Lookahead heuristic: if next_item_size is large, favor bins that can accommodate it.
    //    If post_residual is less than next_item_size, we penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
