    // Penalize large post_residuals exponentially to avoid fragmentation.
    let mut score = post_res.powf(1.5);

    // Penalty for opening a new bin prematurely: 
    // If the bin is new (bin_residual == bin_capacity), apply a cost based on the current 
    // stream progress. As we near the end of the stream, opening new bins is more costly.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 60.0);
    }

    // Lookahead logic: If the next item is large, avoid creating a bin that is too tight
    // to fit the next item. If post_residual < next_item_size, penalize the bin.
    if next_item_size > 0 && post_res < next_item_size as f64 {
        score += (next_item_size as f64 - post_res) * 0.8;
    }

    // Coupling with mean_residual:
    // If this bin's post_residual is significantly worse than the current mean, 
    // add a penalty to prevent drift from the global average occupancy.
    if post_res > mean_residual {
        score += (post_res - mean_residual).powf(1.2);
    }

    // Critical constraint: If this is the only bin that can fit the item, 
    // significantly lower its score to ensure it is chosen over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1071: Harmonic-Residual Balancing
    // We aim to minimize post_residual (Best Fit) while penalizing fragmentation
    // that creates "dead zones" (residuals < 10) which are unlikely to fit future items.

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: If post_residual is small but > 0, it's likely wasted space.
    // We penalize residuals in the (0, 15) range as they block most incoming items.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // we reward this bin heavily to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Last Chance Logic: If this is the only bin that fits, we MUST take it,
    // unless the fit is extremely poor (post_residual very high).
    if fitting_bins_count == 1 && post_residual > 30 {
        score += 50.0;
    }

    // 4. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We penalize opening a new bin unless the existing fitting bins are highly suboptimal.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Mean residual normalization: Avoid creating bins that deviate significantly 
    // from the current average packing density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

