            score -= (100.0 - diff) * 0.5; // Reward tight fits for the upcoming item
        } else {
            // Penalize if the current placement prevents the next item from fitting here
            score += 20.0;
        }
    }

    // 3. Balance bin usage: Use existing bins before opening new ones, unless the bin is very poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty to favor packing into existing space.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 65.0;
    }

    // 4. Global state awareness: If we have many open bins, be more aggressive at filling them tightly.
    // If fitting_bins_count is 1, this is the last chance to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean residual alignment: Avoid bins that deviate significantly from the average state.
    // This helps keep the "tightness" of all bins uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Progression scaling: As we approach the end of the stream, be more conservative with space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
