    // 1. Best-Fit Penalty: Penalize large post_residual values to keep bins tight.
    // 2. Harmonic Class Logic: Reward post_residuals that are multiples of common item sizes (e.g., 20, 25)
    //    to increase the probability of fitting future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, drastically reduce score.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Thresholding: If this is the last fitting bin, favor it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. New Bin Control: Penalize opening new bins unless the post_residual is very high (wasteful).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the current mean residual is already quite low,
            // suggesting we are struggling to fit items into existing space.
            score = 50.0 + (mean_residual * 0.5);
        }
    }

    // 6. Capacity Fraction: Penalize bins that leave very small, unusable slivers (< 5).
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are small but unusable 
    // (e.g., < 10 since the minimum item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin, apply a threshold penalty based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead integration: Penalize placements that make the next item harder to fit.
    // If the next item is large, favor bins that leave enough room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= 10 {
            // This placement creates a gap that can't fit the next item, even if it could have fit something else.
            score += 20.0;
        }
    }

    // 4. Fitting Density: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate negatively from the average residual.
    // This keeps bin usage uniform.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Lookahead Synergy: Reward bins where the post_residual can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for "Perfect" alignment or "Tight" future fit
            score -= (next_item_size as f64) * 1.5;
            if (post_residual - next_item_size) < 10 {
                score -= 20.0;
            }
        } else {
            // Penalty if the current placement leaves a gap too small for the next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 3. Fragmentation Avoidance: Penalize residuals that are small but unusable (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Open Bin Management: Penalize creating a new bin unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavy penalty for opening a new bin if an existing one could fit the item
            score += 50.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Neutralize if it's the only option
            score -= 10.0;
        }
    }

    // 5. Mean Residual Balancing: Favor bins that are closer to the current average fullness
    let current_bin_fullness = (bin_capacity - bin_residual) as f64;
    score += (current_bin_fullness - mean_residual).abs() * 0.1;

    // 6. Progress Scaling: Become more aggressive as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins tightly (Best Fit),
    // but penalize small, unusable residuals (Best Fit Decreasing variant).
    // Use lookahead to reserve space for upcoming items.

    let mut score = post_residual as f64;

    // 1. Penalize "dead space": residuals too small for typical incoming items (e.g., < 15).
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual,
    // prioritize this bin to maximize bin utilization.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Dynamic Thresholding: If we are near the end of the stream, 
    // be more aggressive about filling existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 4. Penalty for opening a new bin: Only open a new bin if the current 
    // options are "poor" (high post_residual).
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty is scaled by open_bins_count to discourage excessive fragmentation.
        score = 25.0 + (open_bins_count as f64 * 2.0);

        // If we have many options that fit well, discourage opening a new bin.
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    } else {
        // Adjust score based on how this bin compares to the global mean.
        // If this bin is "emptier" than average, prioritize it to keep tight bins tight.
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Strategy: 
    // 1. Minimize post_residual (Best Fit).
    // 2. Penalize opening a new bin heavily, but scale this penalty by the remaining stream
    //    so that we are more willing to open new bins early on to keep future flexibility.
    // 3. Use non-linear coupling between post_residual and mean_residual to favor 
    //    bins that stay close to the current average state.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post * post; 

    if is_new_bin {
        // Base penalty for opening a new bin is high.
        // As progress approaches 1.0, the penalty increases to force consolidation.
        score = 8000.0 * (1.0 + progress.powi(2));

        // If there are other bins that could fit this, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 5000.0;
        }
    } else {
        // Reward bins that have a post_residual close to the global mean_residual,
        // which helps maintain uniform bin saturation.
        let deviation = (post - mean_residual).abs();
        score += deviation * 2.0;

        // Lookahead heuristic: If the next item exists, penalize post_residual 
        // that makes the bin too small to accommodate the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 1000.0 * (1.0 - progress);
        }
    }

    // Apply a slight penalty for creating too many open bins relative to progress
    score += (open_bins_count as f64) * 50.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic Class Logic: Reward residuals that match potential next items
    // If post_residual is close to next_item_size, it's a good "harmonic" fit
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + fit_diff);
    }

    // 3. Prevent opening a new bin prematurely
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no existing bins can fit the item
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 65.0; 
        } else {
            score -= 10.0;
        }
    }

    // 4. Harmonic thresholding: Favor residuals that are multiples of common item sizes (e.g., 20, 25)
    // This reduces fragmentation by keeping remaining space usable for future items
    let remainder_class = post_residual % 20;
    if remainder_class == 0 {
        score -= 5.0;
    }

    // 5. Dynamic scaling based on progression
    // As the stream nears the end, prioritize tightly packing remaining items
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Penalty for creating "orphan" residuals (too small to fit any expected item)
    // Assuming 10 is the min item size, anything smaller is effectively dead space
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 7. Favor bins that maintain a high mean residual across the system
    // This helps keep bins "open" for larger future items
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that are too small to fit common items
    // (e.g., < 10) but not zero. This avoids creating "sliver" gaps that are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already active.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, favor it heavily to avoid fragmentation.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // 5. Global Efficiency: If post_residual is very close to zero, it's an excellent fit.
    if post_residual == 0 {
        score -= 10.0;
    }

    // 6. Mean Residual Balancing: If this bin's residual is significantly better than the mean of open bins,
    // push the score down.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins where the remaining space is small.
    score += (post_residual as f64) * 0.5;

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin.
    // We want the residual after the current item to ideally fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect match reward
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.8;
        } else {
            // Penalty for stranding the next item (making it impossible to fit)
            score += 25.0;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless the item fits poorly in all existing bins (fitting_bins_count is low).
    if bin_residual == bin_capacity {
        score += 45.0;
        // If we are forced to open a new bin, make it less attractive than a tight fit.
        score -= (fitting_bins_count as f64) * 10.0;
    }

    // 4. Global Density Balance:
    // If current bin's residual is significantly larger than the mean_residual,
    // penalize placing here to avoid fragmentation.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Urgency:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize small residuals that prevent future items (10-80 range).
    // If the post_residual is small but > 0, it creates "fragmentation" (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Coupling: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Dynamic Thresholding: As the stream nears the end, become more conservative about opening new bins.
    // If we are at the end, penalize new bin creation heavily.
    if bin_residual == bin_capacity {
        score += 15.0 + (30.0 * progress);
    }

    // 4. Fitting Pressure: If this is the only bin that fits the item, reward selecting it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global State Balancing: Avoid cluttering many bins if the mean residual is high.
    // If mean_residual is large, we have plenty of open space; prefer filling existing bins.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 10.0 * (mean_residual / 50.0);
    }

    // 6. Hard constraint: Ensure the new bin candidate is only chosen if existing fits are truly poor.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Penalty for opening a new bin when we have open space.
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit)
    // We penalize larger post_residual quadratically to avoid creating "islands" of wasted space.
    let mut score = post * post * 0.01;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // we heavily favor this bin to consolidate items.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 25.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As we approach the end of the stream, 
    // prioritize closing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: increases as we progress through the stream.
        // If fitting_bins_count is 0, we are forced to open, so we neutralize the penalty.
        if fitting_bins_count > 0 {
            score += 40.0 + (progress * 60.0);
        } else {
            score -= 10.0;
        }
    } else {
        // If the bin is already open, reward placements that move the residual 
        // closer to the mean_residual of other bins to maintain consistency.
        let deviation = (post - mean_residual).abs();
        score -= 5.0 * (1.0 / (1.0 + deviation));

        // Penalize bins that become "too tight" (under 5 units) if they cannot fit the next item,
        // as this often leads to fragmentation.
        if post_residual < 5 && next_item_size > post_residual {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residuals (wasted space)
    // but prioritize tight fits that leave exactly 0 or very small remainders.
    score += (post_residual * post_residual) as f64 * 0.05;

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, 
    // significantly reward this bin to preserve future capacity.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New bin penalty: If this is a new bin (bin_residual == bin_capacity), 
    // add a penalty based on how many other bins could have accommodated the item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 25.0;
        // Also penalize opening a new bin if the item is small relative to capacity
        score += (100 - item_size) as f64 * 0.2;
    }

    // 4. Harmonic/Modulo behavior: Encourage filling bins to specific thresholds 
    // (e.g., 25, 50, 75) to create "standardized" remaining spaces.
    let remainder_mod = post_residual % 25;
    score += (remainder_mod as f64) * 0.5;

    // 5. Global state normalization: If we have many open bins, penalize 
    // opening even more, forcing the heuristic to consolidate.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Final adjustment: Prefer bins that are already closer to the mean_residual
    // to keep the distribution of bin usage uniform.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating unusable gaps (dead space < 10, as items are >= 10)
    // We heavily penalize post_residual values in the range [1, 9]
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Encourage filling bins tightly relative to the mean residual
    // If the post_residual is significantly lower than the mean, it's a good fit
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // Lookahead logic: if the next item fits into this post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Pressure to consolidate: penalize opening new bins or adding to bins if many are open
    // Only apply if this is not a new bin (bin_residual < bin_capacity)
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.2;
    } else {
        // Penalty for opening a new bin if other bins could fit the item
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Progression awareness: become stricter as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins where the remaining space is minimal.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Coupling: If next_item_size fits in the post_residual, 
    // significantly reward this placement to chain items together.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further reward if the post-next residual is very small (near-perfect fit)
        let post_next_residual = post_residual - next_item_size;
        score += post_next_residual as f64 * 0.2;
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily unless 
    // there are no other options (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0; // Force opening if no other bin can fit the item
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current average residual.
    // This maintains a consistent "tightness" across all open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.8;

    // 5. Urgency:
    // As we approach the end of the stream, prioritize closing bins 
    // (smaller post_residual is better) to avoid leaving empty capacity.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Balance Best-Fit (minimizing post_residual) with lookahead (Best-Fit-Decreasing logic) 
    // and a dynamic threshold for opening new bins based on stream depletion.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead zones" (small residuals that are unlikely to fit future items).
    // Specifically, residuals < 10 are often unusable given the item range.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead mechanism: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // 3. Dynamic Threshold for New Bins:
    // As we near the end of the stream, avoid opening new bins unless the fit is excellent.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        // Base cost for opening a new bin is high.
        score += 40.0;
        // As we reach the end of the stream, the cost to open a new bin increases 
        // to force consolidation into existing bins.
        score += progress * 30.0;
    } else {
        // Reward bins that have high mean residuals (more empty space), 
        // effectively pushing items into bins that are already "less full".
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // 4. Scarcity handling: If this is the only bin that can fit the item, 
    // reduce the score to ensure it is picked over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
