pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Penalize creating tiny gaps (fragmentation) that are hard to fill later.
    // We prioritize "Best Fit" (smallest post_residual) but penalize tiny "slivers" (1-5 range)
    // using a non-linear exponential penalty.
    let fragmentation_penalty = if post < 6.0 && post > 0.0 {
        (6.0 - post).powf(2.5) * 5.0
    } else {
        0.0
    };

    // Incorporate lookahead: if the next item is large and won't fit in the current post-residual,
    // we penalize the current choice to keep the residual space flexible for upcoming items.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size as f64 - post) * 0.5
    } else {
        0.0
    };

    // Dynamic scaling based on stream progression: 
    // Early in the stream, be aggressive with packing (Best Fit).
    // Late in the stream, prioritize closing bins to reduce total count.
    let urgency = progress.powf(2.0) * 10.0;

    // Base score is the post_residual (Best Fit heuristic).
    // We want to minimize this, so smaller post_residual is better.
    let mut score = post + fragmentation_penalty + lookahead_penalty + (urgency * (open_bins_count as f64));

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // to force filling existing bins unless they are extremely inefficient.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is poor
        // or if we are forced to (no other fitting bins).
        let new_bin_base_cost = 45.0 + (mean_residual * 0.5);
        score = new_bin_base_cost;
    }

    // Adjust for scarcity: if this is the only bin that can fit the item, 
    // lower the score to ensure we don't skip a necessary placement.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor bins that leave residues which are multiples of common item sizes.
    // We want post_residual to be either 0 (perfect) or large enough to fit future items.
    let harmonic_penalty = if post_residual > 0 {
        // Penalize small "sliver" residuals that are difficult to fill (1..10 range).
        if post_residual < 10 { 25.0 } else { 0.0 }
    } else {
        -15.0 // Strong reward for perfect fits
    };

    // 2. Lookahead Coupling: If next_item_size is large, avoid bins that leave little room.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        if post_residual < 15 { 40.0 } else { 15.0 }
    } else {
        0.0
    };

    // 3. New Bin Thresholding: Prevent opening new bins unless current open bins are very poor.
    // If we are considering a new bin (bin_residual == bin_capacity), increase cost significantly.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_bias = if is_new_bin {
        // Only open new if we have many bins already or if fitting_bins_count is low
        // This acts as a dampener to prevent fragmentation.
        45.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // 4. Mean Residual Balancing: Avoid bins that deviate significantly from the average state.
    // This keeps the pack density uniform across bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    let balance_penalty = deviation * 0.1;

    // 5. Progression Scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    let closing_bias = if progress > 0.85 && !is_new_bin { -10.0 } else { 0.0 };

    score += harmonic_penalty + lookahead_penalty + new_bin_bias + balance_penalty + closing_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

