    // Factor in the global state: if we have too many open bins, prioritize filling them
    // over opening new ones (penalize opening new bins when bin_residual == bin_capacity).
    let new_bin_penalty = if bin_residual == bin_capacity && open_bins_count > 0 {
        20.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Favor bins that are already "tight" to keep the mean_residual low,
    // but balance this against the post_residual to avoid unusable gaps.
    let score = post + fragmentation_penalty + next_fit_penalty + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // We prioritize Best-Fit (minimizing post_residual) but penalize "fragmentation" 
    // where the remaining space is too small to be useful for future items.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation penalty).
    // If post_residual is > 0 but less than the smallest expected item size (approx 10),
    // it's often a dead-space trap.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0; 
    }

    // Lookahead logic: if next_item_size is large, prefer bins that can fit it.
    // If the current post_residual cannot fit the next_item_size, penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // If this is the only fitting bin, we should be conservative.
    // Opening a new bin prematurely when one fits is usually bad.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // If this is a new bin, only choose it if the current open bins are all "bad" fits.
    if is_new_bin {
        // High penalty for opening a new bin unless the mean residual of current bins is high,
        // suggesting that existing bins are already too full to be useful.
        score += 40.0 - (mean_residual * 0.5);
    }

    // Harmonic scaling: favor bins that leave a multiple of 20 or 25 (common factors of 100),
    // as these are more likely to accommodate future items perfectly.
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 5.0;
    }

    // Progression scaling: as we near the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

