        // If this bin is the last chance, reward taking it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 5. Balance against the mean_residual to avoid "outlier" bins.
    // If this bin's post_residual is significantly better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // The goal is to minimize score.
    // Base score is the residual space after placement (Best Fit strategy).
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty for opening a new bin if other options exist
            score += 200.0 + (fitting_bins_count as f64 * 50.0);
        } else {
            // If no other options, normalize the cost of a new bin
            score = 50.0;
        }
    }

    // 2. Lookahead: If next_item fits in the post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Global State: Penalize bins that deviate significantly from the mean residual
    // This encourages packing density uniformity across all open bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Dynamic Time Horizon: As the stream progresses, favor tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    // 5. Critical Thresholding: If this is the last bin that can fit the item, 
    // prioritize it heavily to avoid creating unnecessary new bins later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left in the bin.
    // Lower residual (tighter fit) is generally better.
    let mut score = post_res;

    // Penalty for creating "dead space" (small residuals that are hard to fill).
    // Specifically penalize residuals in the 1-9 range as they are unlikely to fit most items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large and won't fit in this post_residual,
    // we penalize the current choice to favor bins that leave room for future items.
    if next_item_size > 0 {
        let next_fit = post_residual >= next_item_size;
        if !next_fit {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Encourage filling bins towards the end of the stream (high progress)
    // to consolidate items and reduce the final bin count.
    if progress > 0.8 {
        score -= (bin_capacity as f64 - post_res) * 0.5;
    }

    // Balance the number of open bins:
    // If few bins are open, we are more willing to open a new one (lower score for empty bin).
    // If many bins are open, we penalize opening new ones to force consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // If it's the only option, don't penalize too heavily
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Favor bins that align with the current mean_residual to keep bin states uniform
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize "Waste" using Best-Fit Decreasing logic with a lookahead penalty.
    // If post_residual is 0, it's a perfect fit (High reward).
    // If post_residual is small (1-9), it creates "dead space" (High penalty).
    // Use harmonic-like weighting to prefer larger post_residuals if they fit the next_item.

    let mut score = post_residual as f64;

    // 1. Reward perfect fits (Best-Fit principle)
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Penalize "near-miss" dead space (1..10) which is hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 3. Lookahead heuristic: If next_item_size can fit in the current post_residual,
    // we want to preserve that space. Favor bins that leave enough room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. If we are forced to open a new bin (fitting_bins_count == 0),
    // reduce the penalty for opening a new bin by considering the current mean_residual.
    // If our open bins are already very full, opening a new one is cheaper.
    if bin_residual == bin_capacity {
        if mean_residual < 20.0 {
            score += 10.0; // Keep existing bins if they are already tight
        } else {
            score -= 5.0;  // Open new bin if existing ones are fragmented
        }
    }

    // 5. Harmonic scaling: penalize bins that are "almost full" but not "perfectly full"
    // to encourage clustering items into specific bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
