    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize post_residuals in the range (0, 10) heavily as they are usually unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Lookahead logic: if the next item could fit into the current post_residual, 
    // reward this placement (Best Fit strategy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // New-bin logic: If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have too many open bins (high fragmentation pressure)
        // or if it's the only way to avoid leaving a tiny, useless gap elsewhere.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // Apply a heavy bias against opening a new bin unless existing bins are very full
            score += 40.0 + (mean_residual * 0.5);
        } else {
            score += 15.0;
        }
    } else {
        // If it's an existing bin, reward bins that are already partially filled
        // to encourage consolidating items into fewer bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Late-game heuristic: As we approach the end of the stream, be more aggressive
    // about fitting items into existing bins to minimize total count.
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
