    let mut score = post_residual as f64;

    // 2. Lookahead Synergy: If the post_residual is close to the next_item_size, we reward it.
    // We penalize if the next item is too large for the post_residual (wasted potential).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit synergy: subtract score to make this bin highly attractive.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Fragmentation penalty: post_residual is too small to accommodate the next item.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // 3. Global Packing Pressure:
    // If we have many open bins, we want to consolidate (prioritize bins with lower residuals).
    // If we have few open bins, we are more flexible.
    score += (open_bins_count as f64) * 0.1;

    // 4. Mean Residual Balancing:
    // If the current bin is significantly emptier than the average, we prefer filling it.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // 5. New Bin Penalty:
    // Discourage opening a new bin unless the existing fits are extremely poor.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, but scale it by how many bins are already open.
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. Last-Chance Logic:
    // If this is the only bin that can fit the item, we make it artificially attractive 
    // to avoid the new-bin penalty.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
