    // but favor tight fits as we approach the end of the stream.
    let dead_space_penalty = if post_res > 0.0 && post_res < 10.0 {
        (10.0 - post_res).powf(1.5) * (1.0 + progress)
    } else {
        0.0
    };

    // If this is the only bin that fits, we are forced to take it. 
    // Otherwise, penalize new bin creation (bin_residual == bin_capacity) 
    // significantly more as the stream progresses.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 
        } else {
            50.0 + (progress * 100.0)
        }
    } else {
        0.0
    };

    // Use lookahead to discourage leaving a bin in a state that cannot 
    // accommodate the next item.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 0.5
    } else {
        0.0
    };

    // Combine factors:
    // 1. post_res: Prefer smallest residual (Best Fit).
    // 2. dead_space_penalty: Avoid fragments.
    // 3. new_bin_penalty: Discourage opening new bins.
    // 4. lookahead_penalty: Favor states that can handle the next item.
    post_res + dead_space_penalty + new_bin_penalty + lookahead_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
