    // Penalty for opening new bins: if this is a new bin (residual == capacity), 
    // only pick it if the mean residual of existing bins is already very low (tightly packed).
    if residual == bin_capacity as f64 {
        // High penalty for new bin unless the existing bins are extremely full.
        score += 40.0 * (mean_residual / bin_capacity as f64).powi(2);

        // As the stream progresses, the penalty for opening a new bin increases to force consolidation.
        score += 50.0 * progress;
    } else {
        // If it's an existing bin, reward it based on how well it fits compared to the mean.
        if post < mean_residual {
