    // Small gaps (< 10) are rarely useful given the item range [10, 80].
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 * (1.0 - progress);
    }

    // 3. Global State: If we are near the end of the stream, prioritize packing tighter over creating new bins.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. New Bin Management: Discourage opening new bins unless the current options are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, adjusted by current density.
        let density_penalty = (open_bins_count as f64 * 5.0) + (mean_residual * 0.2);
        score += 40.0 + density_penalty;
    } else {
        // Encourage using existing bins that have high remaining capacity to keep others empty.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
