        // or if we are nearing the end of the stream and need to manage remaining bins.
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // Forced opening
        }
        // Penalize opening new bins too early in the stream
        score += (1.0 - progress) * 20.0;
    } else {
        // If it's the last chance (fitting_bins_count == 1), reward using the existing bin
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // 5. Density optimization
    // Favor tighter fits as the stream progresses
    score -= (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
