    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty * 0.5;

    // 4. Global Density Control: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if fitting_bins_count > 0 && bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // 5. New Bin Penalty: Heavily penalize opening a new bin unless existing 
    // options are extremely poor (high post_residual).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0 * (1.0 - progress);
    }

    // 6. Mean Residual Balancing: If this bin's post_residual is significantly 
    // lower than the mean of other bins, it's a high-quality "tight" fit.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
