    // Penalize creating tiny, unusable gaps (1-9 range) unless it's the very end of the stream
    let fragmentation_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.0 - progress).exp() * 5.0
    } else {
        0.0
    };

    // Reward bins that become "tight" (highly filled)
    let tightness_reward = -(100.0 - post).powf(1.5) * 0.1;

    // Lookahead: if next_item_size exists, penalize bins that cannot fit it
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Discourage opening new bins early unless the fit is very poor
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong discouragement for new bins if there are valid candidates
            30.0 + (open_bins_count as f64 * 2.0)
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Factor in the mean residual to keep bins balanced
    let balance_penalty = (post - mean_residual).abs() * 0.5;

    post + fragmentation_penalty + tightness_reward + lookahead_penalty + new_bin_penalty + balance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If it's a new bin, penalize it based on how many items are left and how many bins are open.
    // We only want to open a new bin if the current open bins are "too full" or "too fragmented".
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is the capacity.
        score = bin_capacity as f64 * 0.85;

        // If we have very few items left, we should be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 20.0;

        // If we have many open bins, penalize opening another one.
        score += open_bins_count as f64 * 2.5;
        return score;
    }

    // 2. Harmonic/Residual logic: Reward placements that leave a residual that is a multiple of 
    // common item sizes or fits the next item well.
    // Small post_residuals are generally good (Best Fit), but we want to avoid "dead" space
    // that is too small for any likely future item (e.g., < 10).
    if post_residual < 10 {
        // A tight fit is excellent, but if it's too tight to fit anything else, 
        // it might be better to leave slightly more room if the next item is large.
        score -= 5.0; 
    } else if post_residual < next_item_size {
        // Penalty for creating a "stranded" space that cannot fit the next item.
        score += 15.0;
    }

    // 3. Lookahead optimization: If the next item fits perfectly into the remaining space,
    // prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        if diff < 5.0 {
            score -= 12.0; // Strong preference for leaving room for the next item.
        }
    }

    // 4. Balance the fill across bins: Penalize bins that are significantly below the mean residual.
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    // 5. Last chance logic: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // Base score is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // Penalty for creating "dead zones" (unusable space < 10, as items are >= 10).
    // If post_residual is between 1 and 9, it's effectively dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If current post_residual is too small to fit the next item, penalize slightly.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // New bin logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize based on open_bins_count
    // to discourage starting new bins unless necessary (i.e., when all open bins result in bad fits).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If an existing bin could fit this item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Prefer bins that keep the mean_residual low to maintain bin density.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Progression weight: In the final stages, minimize open bins count aggressively.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We add a penalty for larger post_residuals to prefer tight packing.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Integration: If post_residual can fit the next item, heavily reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
        // Further reward if the resulting space after BOTH items is very small (near 0)
        let remaining_after_next = (post_residual - next_item_size) as f64;
        score += remaining_after_next * 0.2;
    }

    // 3. Last-Chance Logic: If this is the only bin that can fit the item, 
    // prioritize it over opening a new bin (which is usually expensive).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly 
    // from the average fullness, which helps keep future placement options uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. New Bin Penalty: If the bin is brand new (residual == capacity), 
    // add a high threshold cost to discourage opening it unless necessary.
    if bin_residual == bin_capacity {
        score += 45.0; 

        // Dynamic scaling: As we approach the end of the stream, 
        // become more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the waste if we pick this bin. 
    // We want to minimize waste, but prioritize bins that leave "useful" space for the next item.

    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Strongly prefer bins where post_residual is small (tight fit).
    // The current 'score' (post_residual) already favors tight fits.

    // 2. Lookahead optimization: If the next item fits into the post_residual, 
    // we want to reward this bin heavily to keep the next item in the same bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New bin penalty: If we are considering a new bin (bin_residual == bin_capacity),
    // only choose it if the fitting_bins_count is 0 or if the existing bins are extremely full
    // and would result in poor packing for future items.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have existing options.
            score += 45.0; 
        } else {
            // If no bins fit, we must open a new one. Normalize the cost.
            score = 10.0;
        }
    }

    // 4. Global state adjustment: If we have many open bins, prioritize closing them by 
    // filling them up (penalizing large post_residuals more heavily).
    let progress = step_index as f64 / total_items as f64;
    if open_bins_count > 3 {
        score += (post_residual as f64) * progress;
    }

    // 5. Fragmentation avoidance: If post_residual is small but not zero (e.g., 1-9),
    // it is often "dead space" that is hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, which rewards Best-Fit behavior.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely.
    // Scales linearly with progress to become more conservative as the stream ends.
    if is_new_bin {
        score += 25.0 + (progress * 50.0);

        // If there are other bins that could fit this, penalize the new bin heavily.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Non-linear coupling: penalize creating very small residuals (dead space)
        // that are unlikely to accommodate future items.
        // We use a parabolic penalty centered at small residuals.
        let dead_space_penalty = (10.0 - post_residual as f64).powi(2) * 0.5;
        if post_residual < 10 {
            score += dead_space_penalty;
        }

        // Lookahead heuristic: if next_item_size is large, favor bins that can accommodate it.
        // We subtract from the score to make bins that leave enough room for the next item more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        }

        // Reward keeping residuals close to the mean to maintain uniform bin utilization.
        let residual_variance = (post_residual as f64 - mean_residual).abs();
        score += residual_variance * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic/Modulo logic: prioritize leaving "round" space for future items
    // Prefer post_residual that is a multiple of 10 or 20, as they accommodate common item clusters
    let modulo_penalty = (post_residual % 10) as f64 * 1.5;
    score += modulo_penalty;

