    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 4. Scarcity/Density management: 
    // If few bins fit the item, we are forced to use one; if many, pick the tightest fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0; // Avoid opening a new bin if this is the only one that fits
    }

    // 5. New Bin Penalty: Heavily penalize opening a new bin unless the fit is poor
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If the item is large (> 70), opening a new bin is better than ruining a tight bin
        if item_size > 70 {
            score -= 30.0;
        }
    }

    // 6. Global State: Encourage packing into bins that are already "half-empty" (mean_residual)
    // to consolidate waste.
    let deviation_from_mean = (bin_residual as f64 - mean_residual).abs();
    score += deviation_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

