    // If the post_residual is small (e.g., < 10), it is likely "unusable" dead space.
    // We penalize these gaps heavily to encourage fitting items into bins that leave larger, more flexible remainders.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Best-Fit/First-Fit Pressure:
    // If we have many open bins, we want to prioritize filling the ones with lower residuals first to minimize open_bins_count.
    // We reward filling bins that are already tight.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

