    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless no other bins are available or the current fit is extremely poor
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if existing ones work
            score += 40.0;
        }
    } else {
        // If the bin is already open, reward keeping the mean_residual high 
        // to keep "empty-ish" bins available for larger items
        if (post_residual as f64) < mean_residual {
            score += 5.0;
        }
    }

    // Progression weight: as we approach the end of the stream, 
    // prioritize clearing out existing bins more aggressively
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are small but unusable (1..9).
    // These gaps are likely to remain empty for the duration of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to increase packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global Bin Pressure: As the stream progresses, increase the cost of opening new bins
    // to force tighter packing when the remaining items are fewer.
    let progress = step_index as f64 / total_items as f64;
    let open_bin_penalty = (open_bins_count as f64) * (1.0 + progress * 2.0);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // proportional to the number of bins already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bin_penalty;
    } else {
        // If it's an existing bin, reward it slightly to keep bin count low.
        score -= 5.0;
    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the item, 
    // it's a "forced move", so we normalize the score to ensure we don't 
    // prefer a new bin over a last-resort fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residuals (wasted space)
    // We want the post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If post_residual can perfectly fit the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        // High reward for "perfect match" potential
        score -= (100.0 - (post_residual - next_item_size) as f64).powf(1.2);
    }

    // 3. Prevent fragmentation: Penalize opening new bins unless necessary.
    // If the bin is new (bin_residual == bin_capacity), apply a heavy "startup" tax 
    // unless there are no other viable options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Discourage opening new bin if existing ones can fit
        } else {
            score -= 50.0;  // Must open new bin, make it attractive
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly from the average.
    // This helps keep bins packed at similar levels.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 5. Progression scaling: As we approach the end of the stream, prioritize tight packing
    // to minimize the impact of remaining items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size fits in the current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 + progress);
    }

    // 3. Last-Chance heuristic: If this is the only bin that fits the current item, 
    // highly reward it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 4. Global State: If we have many open bins, penalize opening a new one 
    // (bin_residual == bin_capacity) to encourage consolidation.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 5.0);
        }
    }

    // 5. Mean residual balancing: Penalize placing in bins that deviate 
    // significantly from the average residual of open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 6. Tight-fit priority: If the item fits perfectly, prioritize it heavily.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Lower residual is generally better (Best Fit).
    let mut score = post;

    // Penalty for creating "dead space": residuals that are smaller than the smallest likely item 
    // but larger than zero are inefficient. We penalize post_residual values that are 
    // just below the mean_residual of current bins to encourage packing consistency.
    if post > 0.0 {
        score += (post - mean_residual).powi(2) * 0.1;
    }

    // Lookahead logic: if the next item is large and the current post_residual 
    // is too small to accommodate it, we penalize this placement to save the space.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 0.5;
        }
    }

    // Dynamic thresholding: As we approach the end of the stream, prioritize 
    // filling existing bins more aggressively to minimize total bin count.
    // We dampen the penalty for new bin creation as progress increases.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for new bins early on; lower penalty as we reach end of stream.
        score += 40.0 * (1.0 - progress * 0.5);

        // If we have many bins open, penalize opening another one.
        score += open_bins_count as f64 * 2.0;
    } else {
        // If this is the only bin that fits, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Non-linear coupling: penalize very small residuals that are likely to become "stranded" 
    // (e.g., < 10) unless we are near the end of the stream.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
