}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that are hard to fill).
    // Specifically, residuals between 1 and 9 are extremely difficult to fill given the input range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead logic: If the next item can fit perfectly or near-perfectly into the post_residual,
    // reward this bin choice heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            // Reward bins that leave exactly enough room for the next item
            score -= (100.0 - diff) * 0.5;
        } else {
            // If the next item cannot fit, penalize this bin slightly to favor others that might accommodate it
            score += 15.0;
        }
    }

    // 3. Global state awareness:
    // If this is the only bin that can fit the item, we are forced to take it, but if it creates
    // a bad residual, we penalize it less than opening a new bin (which has high overhead).
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 20.0; 
    }

    // 4. New bin handling:
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a fresh bin.
    // We only want to open a new bin if the mean_residual of existing bins is already very small (tight),
    // or if the current item is very large.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: normalized by how much space is left in existing bins.
        // If mean_residual is large, we have plenty of space elsewhere, so opening a new bin is bad.
        score += mean_residual * 0.8;

        // If we are late in the stream, opening new bins is very costly.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
