    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize this bin.
    if next_item_size > 0 {
