            score -= 15.0;
        }
    }

    // 3. Global State Balancing: Avoid crowding too many bins if we are early in the stream.
    // Discourage opening new bins early unless the fit is perfect (Best Fit logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
