            score += 60.0 + (progress * 40.0);
        } else {
            // If it's the only option, normalize to avoid extreme values
            score = 25.0;
        }
    } else {
        // 4. Mean Residual Pressure: If this bin is significantly emptier than the average,
        // it is a good candidate to fill to reduce bin fragmentation.
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score -= residual_diff * 0.2;
    }

    // 5. Finality Adjustment: As we approach the end of the stream, favor closing bins
    // by prioritizing the tightest fits (Best Fit decreasing).
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
